quests[30675] = { id = 30675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Hozen Treasure", description = "The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X on a beach.\n\nIs there buried treasure somewhere on this island?", objectives = "Find the Buried Hozen Treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30677] = { id = 30677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shuttle Service" }
quests[30678] = { id = 30678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Bombing Fish In A Barrel", description = "Turns out these rays are not as easy to catch as I thought! You seem like a pretty smart <guy/gal>, think you can help me out?\n\nI made the bombs but have been having trouble using the raft with my hurt leg. The rays are common in the shallows just west of here. Take the bombs and use my raft to bring me back their stingers!\n\nOh yeah, watch out for the hammerheads!", progress = "Find any sting rays in the shallows?", completion = "Looks like you're pretty handy with those bombs!", objectives = "Use the Goblin Fishing Bombs to kill 3 Sting Rays and bring back their stingers to Fiznix. The Rays can be found in the shallows west of Anglers Wharf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30680] = { id = 30680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "Oh thank you, thank you, thank you. If you hadn't come along...\n\nWait! There must be other survivors in the Nook like me!\n\nPlease, {class}, I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30681] = { id = 30681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "Oh, thank you! There's no way I could have made it back on my own.\n\nCome to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30682] = { id = 30682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "I can't believe you made it here!\n\nI don't know how much longer I could have stayed hidden in here.\n\nI'm sure that there are others. {class}, we have to rescue them! Then we can go to Shado-Pan Fallback. The master there will know what to do!", completion = "We didn't know that there were any survivors out there.\n\nThank you for bringing them to safety, {name}.", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30683] = { id = 30683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Traveler's Misfortune", description = "Did you have to throw our supplies at them?! Why not use your weapon? Maybe fancy spells or kicks? Why the supplies?!\n\nNow we don't have enough to last us, especially with Nephew Bentnail here. His appetite is like a yeti's!\n\nYou threw it, you get us more. There is wreckage down the path. Maybe you will find supplies there.", progress = "Nephew Bentnail has already eaten two days worth of food. I hope you found us more!", completion = "You were attacked by a mogu? That sounds terrible!\n\nI hate to ask, but did you manage to pick up any supplies while you were fighting for your life?\n\nNo?! This is very bad luck.", objectives = "Search the Abandoned Wreckage for supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30684] = { id = 30684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeker's Folly", description = "I'm sure your pandaren friend has some ideas about what the mogu are after.\n\nHe headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific:\n\n\"The {class} must endure the trek alone, with only <his/her> thoughts. <He/She> will honor each shrine before meeting me at the top.\"\n\nThe path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.", progress = "There are two shrines on the path below us, and one more just behind us.", completion = "Ah, you made it, and you honored the shrines.\n\nI knew you could handle it.", objectives = "Brave the path of Seeker's Folly to find Lorewalker Cho, stopping to reflect at the three shrines along the way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30690] = { id = 30690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unmasking the Yaungol", description = "Simply killing Kobai will accomplish nothing, as he is possessed by a particularly powerful and destructive Sha - Malevolent Fury.\n\nYou will use the trap I have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take control of you.\n\nDefeat him, and we will have made a victory of this tragic situation. You can find him to the north of the retreat, where he taunts us in insane rage.", progress = "Is Malevolent Fury gone?", completion = "I should feel shame at the loss of the village. I should feel great pride in your success. \n\nI should feel many things, but must not allow myself to. Until our struggle with the sha is complete, we must maintain total control of our emotions.", objectives = "Lure Kobai into the Blinding Rage Trap, steal the Mask of Malevolent Fury from him, and then defeat Malevolent Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30691] = { id = 30691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misery", description = "While you are in the water below, you should slay Nahassa, the mortbreath patriarch. He suffers. I can feel his death cries ululating up to the surface of the lagoon.\n\nFind his cave, and put him out of his misery. Not because it will solve Marista's crocolisk problem. Simply out of mercy.", progress = "Please, {name}. Even the great beasts of this world have a right to die in dignity.", completion = "Nahassa's fevered suffering has come to an end.", objectives = "Put Nahassa out his misery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30692] = { id = 30692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Trail: To Kota Basecamp", description = "This here's hozen lands. Very dangerous. But grummles must trek through. Supplies must reach the Serpent's Spine.\n\nGo, protect the next wave of grummles on their trek to Kota Basecamp.\n\nIf at least one survives, good fortune will find its way to you.", progress = "Welcome to Kota Basecamp, friend of grummles.", completion = "Ha ha! Hero of grummles! Welcome to Kota Basecamp. Enjoy good fortune for most happy grummle delivery.", objectives = "Protect a group of grummles from the Burlap Waystation to the Kota Basecamp. At least one grummle must survive.\n\nIf you lose your grummles, you can search the Burlap Trial or return to the Burlap Waystation and wait for the next group to leave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30694] = { id = 30694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tread Lightly", description = "My students tell me the surrounding area is littered with deadly traps, no doubt set by the saurok. Stumbling into one gets you a face full of spikes.\n\nAs the saying goes: \"The Way is rife with danger - tread lightly, and with scrutiny.\"\n\n<Koro hands you a long tree branch.>\n\nHere, this is scrutiny.\n\nIt should be long enough to set the traps off at a safe distance.", progress = "Well, I don't see any spikes in your face. That's a good sign.", completion = "Every trap you sprang is a life saved, be it pandaren, beast, or otherwise. Nobody deserves an honorless death like that.", objectives = "Use \"Scrutiny\" to set off 10 Riverblade Spike Traps from a safe distance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30695] = { id = 30695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahead on the Way", description = "Huge maws of despair are spewing out sha from the pagodas on either side of the temple. Meanwhile, your impromptu training in the Way continues.\n\n\"She who mends torn umbrella will be more dry than she who strikes at rain.\"\n\nWhile I take issue with that particular lesson--sometimes punching the rain can be quite effective--the meaning holds true in this case.\n\nTake out those maws of despair and give my order a chance at reclaiming the temple grounds.", progress = "Koro said there's a pagoda on either side of the temple. Let's find them and wipe out the sha presence in both.", completion = "Koro's metaphors can get a little tiring, but there's always true wisdom behind them.", objectives = "Kill the Maw of Despair in both the eastern and western pagodas at the Temple of the Red Crane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30698] = { id = 30698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenger Hunt", description = "YOU!  You're just who I have been looking for!\n\nI need more parts for my goblin fishing bombs but I hurt my leg and can't collect them myself.\n\nYou see those shipwrecks nearby?  I bet they have just what I need if you can get to it and fish it out.  Take my fishing raft and see what you can find!  My buddy has been trying to help me out too so you might find some extra rafts near the wreckage, feel free to use em' too.", progress = "Did you find the shipwrecks?", completion = "Looks like you found plenty of parts, another set of fishing bombs coming right up!  Thanks {name}!", objectives = "Use the Goblin Fishing Raft to fish up 15 Rusty Shipwreck Parts out of the floating debris near the shipwrecks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30699] = { id = 30699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Winter's Blossom", description = "The battle against the Sha is eternal - we can not leave this place. \n\nBut I am troubled by the absence of reinforcements from the Monastery given that we sent for them days ago. \n\nYou have performed admirably, perhaps you could travel to Winter's Blossom, our base camp on the way to the Shado-Pan Monastery. Speak with Lin Silentstrike once you arrive - he should know what is happening. To get there, travel north of the village and follow the road through Shado-Li Basin to Winter's Blossom.", completion = "Shado-Master Chong sent you, hmm?\n\nYes, we received his request for reinforcements.\n\nWe are in no position to grant it, however. We've just concluded a battle of our own, and the monastery's been locked up tight. \n\nWe can't even get reinforcements here, and we're just down the hill!", objectives = "Speak with Lin Silentstrike at Winter's Blossom in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30700] = { id = 30700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapclaw", description = "A giant, poisonous crab is wrecking havoc on our local abalone stores.  I need you to go down into narsong trench and take it out!", progress = "Did you take out that nasty crawler?", completion = "That is quite the claw, Snapclaw must be bigger than I thought!  No matter, job well done {name}!", objectives = "Kill Snapclaw in a cave at the bottom of Narsong Trench and return with his claw as proof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30701] = { id = 30701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viseclaw Soup", description = "Nothing tastes quite like viseclaw soup.  It's a krasarang specialty!\n\nI was just about to start up on a new batch when I realized I am missing a key ingredient, the eyes!\n\nI need you to kill the viseclaw fishers on the beach and return with their eyes for the soup!", progress = "How many of their beady little eyes did you get?", completion = "Thanks {class}, this might be my best batch of soup yet!", objectives = "Kill Viseclaw Fishers on the beach and return with 16 eyes to make some yummy soup.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30704] = { id = 30704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen in the Mist" }
quests[30705] = { id = 30705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Log" }
quests[30706] = { id = 30706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angry Scribblings" }
quests[30710] = { id = 30710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provoking the Trolls", description = "We've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all.\n\nMy husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so.\n\nWe will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.", sourceObjective = "Kill 10 Zandalari Stalkers and 5 Zandalari Hexers", sourceObjectiveStatus = "unverified-source-field" }
quests[30714] = { id = 30714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Leaders", description = "And, now they fear you.\n\nTheir leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them.\nMake them hurt. For us.", sourceObjective = "Kill the Zandalari Blademaster and Zandalari Mage", sourceObjectiveStatus = "unverified-source-field" }
quests[30715] = { id = 30715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line Unbroken", description = "When we regrouped after their initial attack, we numbered three less. You can fight, and we must plan our defense should these cursed yaungol attack again. \n\nIf you would help us, grant our fallen comrades their last rites, and recover their armor. You will find their bodies to the west, near the gate.\n\nAnd try to keep the birds off them.", progress = "Our comrades, are they at rest?", completion = "Good. I will see to it that the armor is returned to their pupils.", objectives = "Lay Shado-Master Zhiyao, Liu of the Thousand Blows and Shiya Boldblade to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30716] = { id = 30716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Hope", description = "Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of his spirit run through the forests and beaches of the island, watching us and testing us.\n\nProve your dexterity in the eyes of Chi-Ji, {name}. Find and catch the spirits of the crane.", progress = "Return when you are finished, {name}. Now go!", completion = "Chi-Ji smiles on you.", objectives = "Touch 3 Spirits of the Crane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30717] = { id = 30717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifts of the Great Crane", description = "The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they leave behind are a gift for us to appreciate.\n\nWe use these feathers to adorn our garments and to fletch arrows. But first... they must be gathered.", progress = "Even the smallest, flimsiest feather is proof enough that Chi-Ji loves us.", completion = "Thank you, {name}.\n\nReturn to us again soon.", objectives = "Obtain 10 Gifts of the Great Crane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30718] = { id = 30718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students of Chi-Ji", description = "Our order prides itself on excellence in combat. We hone these combat skills by dueling one another, here on the Cradle of Chi-Ji.\n\nProve yourself in the eyes of the Red Crane. Venture south, into the center of the island, and duel with your fellow students.", progress = "Your trial is not yet complete, {name}.", completion = "With every battle - a win or a loss - you improve. You become faster, hardier, cleverer... better.", objectives = "Duel 10 Students of Chi-Ji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30719] = { id = 30719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Cradle of Chi-Ji Progress Bit 01" }
quests[30720] = { id = 30720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Cradle of Chi-Ji Progress Bit 02" }
quests[30721] = { id = 30721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Cradle of Chi-Ji Progress Bit 03" }
quests[30722] = { id = 30722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Cradle of Chi-Ji Progress Bit 04" }
quests[30723] = { id = 30723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor, Even in Death", description = "Hmm... If Shado-Master Chong trusted you, perhaps you can help us.\n\nThe yaungol are our enemies.\n\nStill, we must prove we are better than they. We will show them honor in death.\n\nAs after most battles, the carrion birds have begun gathering. Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered at the battlefield to the west.", progress = "Killing those birds may not soothe my anger, but at least it proves that we are better than our enemies. They would not do such a thing.", completion = "Good. After what they have done, I would not show the Yaungol kindness in life. But neither will I allow their bodies to be eaten by the birds.", objectives = "Kill 12 Kun-Lai Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30724] = { id = 30724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Wall!", description = "They are attacking again!\n\n<Lin looks to the Ox Gate.>\n\nArchers... on the wall!\n\nI need you to get up there. My wife Suna went to scout the wall with that fool Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that ridiculous ale lift contraption...\n\nIt matters not. Get a kite from Len, to the west, and then get up there and find my wife. She'll know what to do next.", completion = "Wow, that was quite a bit of kite-flying there. Good job getting up here and not dying.\n\nIt's good you're here, too. Lao-chen's got an idea he's working on, but in the meantime we've got yaungol to deal with.", objectives = "Speak to Kite Master Len at Winter's Blossom in Kun-Lai Summit to take a kite up to the Ox Gate. Once there, speak to Suna Silentstrike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30725] = { id = 30725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane", description = "We regularly organize one-on-one duels with trainees that we think are well-suited for one another. We have found one such trainee for you, {name}.\n\nHer name is Ellia Ravenmane. This will be her first duel, too. She will be waiting for you at the pavilion just to the south of here.", completion = "Very good!\n\nThe next time you return, you will face a new challenger. Continue winning, and your favor in the eyes of Chi-Ji will increase.", objectives = "Defeat Ellia Ravenmane at the Angkhal Pavilion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30726] = { id = 30726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minh Do-Tan", description = "Your next challenger is another relatively new trainee. His name is Minh Do-Tan, and he has won his last two matches.\n\nHe will be waiting for you near the crane statue to the south.", progress = "Fight hard, {name}.", completion = "Well done, {name}. You are beginning to make a name for yourself.", objectives = "Defeat Minh Do-Tan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30727] = { id = 30727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane: Rematch", description = "Ellia Ravenmane requested a rematch with you. She seems to identify you as her \"rival\".\n\nWe discourage rivalries here within the Cradle of Chi-Ji, but we rarely decline a rematch request. You will find Ellia near the Pedestal of Hope, on the island's eastern side.", completion = "Twice fought, twice defeated. It stands to reason that Ellia will not be requesting more rematches anytime soon.", objectives = "Defeat Ellia Ravenmane near the base of the Pedestal of Hope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30728] = { id = 30728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Long-Fat", description = "You have been matched with a... special trainee. His name is Fat Long-Fat.\n\n<Thelonius chooses his words carefully.>\n\nFat Long-Fat... operates outside of the normal rules of combat. He does not fight every day, and when he does, he chooses his competitor. Today, for some reason... he has selected you.\n\nYou will find him atop Angkhal Pavilion.", completion = "Of course you won. Fat Long-Fat does not fight to win. He fights for... other reasons.\n\nI fear I've spoken too much about this subject already. From now on... no more questions about Fat Long-Fat.", objectives = "Defeat Fat Long-Fat at the top of Angkhal Pavilion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30729] = { id = 30729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia Bates", description = "We welcome all kinds here within the Cradle, as long as they recognize and subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes from the human kingdoms to the northeast. She goes by the rather foreign-sounding name of Julia Bates.\n\nShe is your next challenger. You will find her on the island's western shore.", completion = "Another fight handily won. I anxiously await your next match, {name}.", objectives = "Defeat Julia Bates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30730] = { id = 30730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dextrous Izissha", description = "Jinyu normally avoid our order, but every few years, we find one that subscribes to the way of the Crane. One such jinyu is Dextrous Izissha.\n\nIzissha is your next challenger. He waits for you on the island's southwestern shore.", completion = "Excellent work, {name}! You continue to gain favor in the eyes of Chi-Ji.\n\nYour next battle will be one to remember. You will not be fighting a trainee. Instead, you will face one of your trainers.", objectives = "Defeat Dextrous Izissha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30731] = { id = 30731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuo-Na Quillpaw", description = "Most of the duels within the Cradle take place between two trainees. Rarely, when a trainee exhibits a rare amount of skill, they will have an opportunity to duel their trainer.\n\nToday, you duel against Kuo-Na. She will be waiting for you at the Pedestal of Hope.", completion = "You continue to impress, {name}.\n\nCome again soon. Your training is not over yet.", objectives = "Defeat Kuo-Na Quillpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30732] = { id = 30732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane: Revenge", description = "Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her duties on the island, instead focusing on personal training, with the intent to defeat you in battle.\n\n\"I will destroy {name},\" she said.\n\nI have honored her request for a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a dangerous direction.", completion = "I will consult directly with Chi-Ji about Ellia's behavior. She treads on thin ice.", objectives = "Defeat Ellia Ravenmane at Dome Balrissa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30733] = { id = 30733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tukka-Tuk", description = "You are making a name for yourself, {name}. I received a challenge from one of our more skilled competitors. He believes you are not as strong as you seem.\n\nHis name is Tukka-Tuk, the hozen. If you've ever fought against hozen before, you know that their apparent juvenility belies their battle acumen. Good luck.", completion = "Well done, as usual.\n\nI trust I will see you again soon.", objectives = "Defeat Tukka-Tuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30734] = { id = 30734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huck Wheelbarrow", description = "Usually our trainees are adventurers like yourself, or monks from Tian Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet trainees that have no fighting experience whatsoever.\n\nHuck Wheelbarrow is one such trainee. He has requested a duel with you. Look for him on the island's western shore.", completion = "There remains only one trainee ranked higher than you.\n\nI have a feeling that you will be facing him when you return.", objectives = "Defeat Huck Wheelbarrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30735] = { id = 30735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mindel Sunspeaker", description = "Our highest-ranked trainee is an outsider like you. It is both strange and exciting to live in a time when so many foreigners have embraced the way of the Crane.\n\nYour challenger's name is Mindel Sunspeaker, and he awaits you within Angkhal Pavilion.", completion = "You are now our highest-ranked trainee. You are no longer obligated to participate in trainee duels. Congratulations!\n\nOf course, there are still other ways to prove yourself. I have the feeling I will be seeing you again...", objectives = "Defeat Mindel Sunspeaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30736] = { id = 30736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yan Quillpaw", description = "You have already defeated Kuo-Na Quillpaw. You have not yet fought her brother, Yan.\n\nHe will meet you at the Pedestal of Hope, and he will not hold back. His reputation as a trainer is at stake.", completion = "And with that victory, I suppose we've run out of challengers for you to fight! Other than me, of course.\n\nBut... I don't fight. I mean, you wouldn't want to fight me. It would... not go well for you.", objectives = "Defeat Yan Quillpaw at the Pedestal of Hope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30737] = { id = 30737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Long-Fat: Rematch", description = "Fat Long-Fat has requested another match with you. I find this strange. And concerning.\n\nHe will be waiting atop the Dome Belrissa.", completion = "I believe I understand why he wanted to fight you a second time, though I need to speak with Chi-Ji before I can be sure.\n\nCome back soon, {name}. I think it is time you learned the true nature of Fat Long-Fat.", objectives = "Defeat Fat Long-Fat atop Dome Belrissa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30738] = { id = 30738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelonius", description = "When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still plan to tell you that secret... after I determine your worth.\n\nI will meet you on the western shore, and we will duel.", completion = "You are truly worthy of the secret of Fat Long-Fat. Here it is:\n\nFat Long-Fat and Chi-Ji are one and the same. Fat Long-Fat is the Red Crane.\n\nHe believes that the Cradle is in great danger.\n\nHe believes there is one person that can save it.\n\nHe believes that you are that person, {name}.\n\nStay in touch.", objectives = "Defeat Thelonius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30739] = { id = 30739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Ravenmane: Redemption", description = "Ellia Ravenmane, your rival, has returned. She demands that you meet her atop the Pedestal of Hope.\n\nYou need to understand, {name}... something horrible has happened to her. She has changed. You will see for yourself when you arrive at the pedestal.\n\nGood luck, {name}.", completion = "The Cradle of Chi-Ji has long been a bastion of hope; a place free of despair. Ellia Ravenmane tried to plant the seeds of despair on our island... and you stopped her.\n\nWe owe you a debt of gratitude, {name}. You are welcome to return whenever you like.", objectives = "Defeat Ellia Ravenmane atop the Pedestal of Hope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30740] = { id = 30740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of Chi-Ji", description = "While you will always hold a place of honor among our order, you are still welcome to participate in our duels.\n\nOne of our current champions awaits you in the Dome Balrissa. I know that they would be honored to duel with you.", completion = "Done masterfully, as always.\n\nWe hope to see you again soon, {name}.", objectives = "Defeat a Champion of Chi-Ji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30742] = { id = 30742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shut it Down", description = "I mussed up. Bad.\n\nIt's hard work cutting seeds out of kafa berries! But I noticed goots eat the berries up and give back the seeds... in a day or so.\n\nI fed everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", completion = "Thank you, friend. Let this be a lesson to you: never feed the goots.", objectives = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30743] = { id = 30743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gourmet Kafa", description = "It was genius: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET.\n\nBut it's over now. Uncle is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so I can find it easily when the mountain is safe again.", completion = "Great, I'll get up there and... harvest them soon.\n\n<Cousin Gootfur begins wrapping long strips of linen around his hands.>\n\nCan't believe I thought this was a good idea.", objectives = "Mark 15 Kafa'goot \"Deposits\" on Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30744] = { id = 30744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nI pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", objectives = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30745] = { id = 30745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen they ate the goots full of kafa...\n\n<Keenbean shoots Gootfur a mean glance.>\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", progress = "Don't wanna fight yetis? Can't say I blame you.", completion = "You made it!\n\nYeti's are tough enough on their own - can't imagine what a cranky kafa-addict yeti must be like. You brave. Or lucky. Or dumb.\n\nMaybe all three.", objectives = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30746] = { id = 30746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fair Trade", description = "<The roar bellows out again, louder and more fierce than any of the yetis you've encountered so far. Again, a grummle voice replies...>\n\nEep! Please, great Kota Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise!\n\n<The beast called Kota Kon answers with another meaty roar.>", progress = "Kota Kon wants more kafa, but I already fed her all I have! Then I tried giving her a nice bow, but she's not satisfied!\n\n<The terrified grummle gulps and leans in close to whisper.>\n\nI think she can smell the kafa I drank for breakfast...", completion = "You brought kafa?!\n\nYou...\n\nMagnificent...\n\nLuckydo...\n\nHurry, let's give it to her! Maybe she won't have us both for snack...", objectives = "Bring the Bundle of Kafa'kota Berries to the Lair of Kota Kon, near the top of Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30747] = { id = 30747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Grind", description = "Okayyy... well, she's not eating anybody. That's a good start.\n\nShe must want more kafa, but we gotta give her somethin' to do with all the extra energy...\n\nI got it! The Burlap Trail! She can smash hozen out there all day!\n\n<Burrberry turns to the massive beast.>\n\nWhat do you think, pretty girl? Wanna smash hozens?!\n\nI think so. Here, feed her my emergency flask of kafa. She likes you.", progress = "Don't push our luck... we promised her hozens-smashies.", completion = "Wow! That was VIOLENT.\n\nNot sure what I was expecting...\n\nThanks to you, I think we may have just formed a mutually beneficial relationship with the Terror of Kota Peak.", objectives = "Feed the Flask of Kafa to Kota Kon at Kota Basecamp, then kill 100 Hozen along The Burlap Trail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30750] = { id = 30750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off the Wall!", description = "The yaungol on the wall here are providing covering fire for the ones below. I don't know what Lao-chen is thinking, but I want you to deal with these archers.\n\nThe good news is, up here we've got the spirit of the Ox helping us. When they're weakened, the ox spirit will stun them and you can use it to knock 'em off the wall.\n\nYou'll find the archers just out that door.", progress = "Come on, come on.", completion = "Ha! I could see them flying. Good work.", objectives = "Kill 12 Osul Veteran Archers or Osul Fire-Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30751] = { id = 30751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Terrible Sacrifice", description = "I have an idea, and... am prepared to make a terrible sacrifice.\n\nAs much as I know that we need my stout brew, to fortify our defenders for the long-term security of the Ox Gate...\n\nIt is too painful to discuss details now, but please - while you are up here defending the wall, gather the barrels of oil they are using to light their arrows. We will need them.", progress = "Do you have the oil?", completion = "Alright. I am off to prepare our next move. Good luck, friend.", objectives = "Gather 6 Barrels of Yaungol Fire Oil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30752] = { id = 30752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbelievable!", description = "I simply refuse to believe the guards will not grant us entry to the monastery should we impress upon them the seriousness of the situation.\n\nFriend, go east, to the sentinel in front of the Monastery, and demand admittance. I will come with you.", progress = "Unbelievable!", completion = "No... this is worse than I could have possibly imagined. The monastery itself has been compromised...", objectives = "Speak to the Shado-Pan Monastery Sentinel to gain entrance to the Shado-Pan Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30753] = { id = 30753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jumping the Shark", description = "There is only one way to kill sharks where I come from, with your bare hands!\n\nI dumped a good amount of chum in the water just off the dock here, this place should be crawling with the local reef sharks in no time.  Hop on the first one you see and take it out!", progress = "Did you show that shark who's boss?", completion = "That was a huge shark you took out {name}!  Color me impressed!", objectives = "Kill a frenzied reef shark with your bare hands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30754] = { id = 30754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bright Bait", description = "Certain fish are only attracted to bright lights.  The forest north of here is home to a local pandaren firefly called a suncrawler.\n\nYou should be able to find them on the base of the tree trunks all around that area.  Bring me back a handful of them and I can use them for bait!", progress = "Any luck with those suncrawlers?", completion = "These should do nicely {name}.  Thanks for the help!", objectives = "Collect 7 Suncrawlers in the forest north of Anglers Wharf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30757] = { id = 30757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord of the Shado-Pan", description = "Our lord, Taran Zhu, has been overcome by a sha of pure hatred. The whole monastery has been lost!\n\n{class}, you must find a way to free him of this possession. Last I knew, he was meditating in the Grove of Falling Blossoms.", completion = "Thank you, {class}. I am cleansed of all hatred.\n\nKnow that you are a hero of the Shado-Pan.", objectives = "Rid Taran Zhu of his possession by the Sha of Hatred.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30759] = { id = 30759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sotelo's Quest", description = "Push the plunger.\n\nPUSH IT!", objectives = "Use Sotelo's Plunger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30763] = { id = 30763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piranha!", description = "Certain fish are very difficult to catch.  The wolf piranha falls squarely into this category.\n\nLucky for me that you showed up!  Put those fishing skills to the test and bring me back a few from the krasarang river due northwest of here.", progress = "Any luck?", completion = "I see you still have all your fingers, nice work.", objectives = "Fish up 5 Wolf Piranha from the Krasarang River in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30765] = { id = 30765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regaining Honor", description = "{name}, the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner.\n\nYou have to kill Humongous and regain Zhen's honor! If you don't, I will.", objectives = "Retrieve Zhen's Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30766] = { id = 30766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profiting off of the Past", description = "<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.>\n\n<There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>", sourceObjective = "Collect 11 more Mogu Relics.", sourceObjectiveStatus = "unverified-source-field" }
quests[30767] = { id = 30767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risking It All", description = "Wait, what?! How could he be so reckless? Blowing the ship free is insane! They could kill Shen-zin Su, and all of us with it. \n\nI know we don't have much time, but we need to think of another way...", completion = "The first step is done, but now we must save Shen-zin Su!", objectives = "Remove the thorn from Shen-zin Su.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30768] = { id = 30768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Husband...", description = "Lin...\n\nI don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit around waiting for everyone else to catch up.\n\nOnce Taran Zhu opens the doors to his precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's alright.", completion = "Good. Looks like the rest of the Shado-Pan decided it was a good time to catch up.", objectives = "Meet up with Suna Silentstrike at Longying Outpost in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30769] = { id = 30769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Assault", description = "Now that we have had time to assess our enemies' weaknesses, it is time for us to deal the yaungol a direct blow.\n\nGo and confront the Osul Sharphorn up the mesa to the west.\n\nLet them know that we are here, and that we are not scared of their threats.", completion = "Well done, {name}. I hope you showed those cretins no mercy.", objectives = "Kill 6 Osul Sharphorns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30770] = { id = 30770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Rampant", description = "There is one thing that every army needs, and that is a supply line.\n\nThe enemy camp to the west contains a large beast herd, which serves as the yaungol army's main source of food.\n\nLuckily for us, the yaks and mushan beasts of this region are easily scared.\n\nSneak in, give the beasts a good slap, and watch the results.", completion = "Ohohoho! I saw those animals trailing dust from up here.\n\nThose yaungol are probably still wondering what happened.", objectives = "Scare 8 Long-Haired Yaks or Steppebeasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30771] = { id = 30771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfect Pitch", description = "When the Osul tribe goes to war, they coat their spears and arrows with a highly flammable, ever-burning pitch.\n\nThey use this terrible weapon to shed not only blood, but to raze the homes of their enemies.\n\nI need you to collect some of this pitch while you are in their camp.\n\nWe will use it to show the yaungol that when you play with fire, you can get burned.", progress = "The yaungol are not content merely to defeat their enemies. No, they would rather destroy and decimate them.", completion = "It still smells fresh.\n\nGood job, {name}.", objectives = "Collect 8 Dark Pitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30772] = { id = 30772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Red", description = "Ahead of us is the main thrust of the yaungol army.\n\nHere, they prepare their vast army to attack the villages of Kun-Lai.\n\nIf we strike at the Osul now, we can cut them at their very core.\n\nRemember, for every of their number that we strike down here, we save one of our own back at home.", completion = "That should put a serious dent in their numbers.\n\nI doubt they will be able to recover from such losses.", objectives = "Kill 8 Osul Marauders or Osul Spitfires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30773] = { id = 30773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pitching In", description = "The yaungol's siege weapons - those ballista spearthrowers down there - are tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit.\n\nThose terrible weapons must be destroyed.\n\nTake these explosives. I've covered them in the pitch that you collected.\n\nToss them at those ballistas, and we'll give the yaungol a little taste of their own medicine.", progress = "Fire is a cruel weapon. Luckily, we are only using it to destroy weapons of war.", completion = "Good, {class}.\n\nNow that they cannot hide behind their siege weapons, they have no choice but to face us.", objectives = "Use Ban's Explosives to destroy 6 Osul Ballistas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30774] = { id = 30774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranger Rescue", description = "I must ask a most important task of you, {name}.\n\nSomewhere among the cages in the Osul camp is my husband, Lin. He is the light of my world.\n\nPlease find him and return him to me, and save as many of our fellow Shado-Pan as you can as well.\n\nYou should find keys to those cages on the Osul Marauders.", progress = "How did it go?", completion = "I am truly sorry to hear that Lin did not make it.\n\nSuna is taking the news quite hard. She will forgive me in time.\n\nAs for the rest of the Shado-Pan that you saved, well, I am very grateful to see them returned safe and sound.", objectives = "Unlock Drywood Cages to save 4 Longying Rangers and Lin Silentstrike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30775] = { id = 30775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exile", description = "What is there to say, stranger?\n\nI fought Jung Duk and lost. I was the fool to believe he would fight fairly.\n\nNow, my own brothers turned against me, and here I am, speaking to our enemies.\n\nI know you have come for Osul blood.\n\nI only ask that you hunt down the three who betrayed me.\n\nUrang, who poisoned my drink. Ku-Tong, who bent my spear. And Battat, whose dagger slipped into my side as my victory was assured.\n\nDo this, and I can die in peace.", progress = "How could they have betrayed me? They were once my brothers!\n\nWhy did they turn on me? WHY?\n\nI hate them! I will slaughter them all!", completion = "It pleases me to know those cowards died at your hands.\n\nPerhaps now, this burning tide in my heart will ebb.", objectives = "Kill Urang, Ku-Tong, and Battat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30776] = { id = 30776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jung Duk", description = "THIS. IS. WAR.\n\nI will have the heads of everyone who took Lin from me. EVERYONE!\n\nWe will begin with the Osul leader, Jung Duk.\n\nTake this Shado-Pan war banner and place it at the center of their camp.\n\nJung Duk will have no choice but to face you.\n\nShow him no mercy, {name}.", progress = "Jung Duk's legacy is written in the blood of innocents.", completion = "Jung Duk is dead at last.\n\nHundreds, perhaps thousands, lost their lives due to his violent aggression.\n\nThough they are not here to witness his demise, they owe deep gratitude to your bravery today.", objectives = "Plant the Shado-Pan Banner on the Ceremonial Pile, then kill Jung Duk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30777] = { id = 30777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Suna", description = "I have bad news. When I returned, Suna was already gone.\n\nThe others say that she took her things and headed down the road to the east, muttering about hunting down the source of the yaungol aggression.\n\nI cannot allow her to venture into dangerous territory alone.\n\nI've already prepared a group of soldiers to push further east.\n\nWe are leaving shortly. Hop on the caravan if you wish to travel with the Shado-Pan. You can also meet us there if you wish.", completion = "Well, we made it.", objectives = "Speak to Ban Bearheart after arriving at Hatred's Vice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30778] = { id = 30778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust to Dust", description = "If we are to make camp here, we cannot leave all of these yaungol bodies lying to rot.\n\nTake this torch and set fire to the villagers' corpses.\n\nThe incense from the torch should purify the earth and air around them as well.\n\nEven our enemies deserve to be laid to rest.", progress = "The stench of death is overpowering.", completion = "Good work, {name}.\n\nHopefully, their spirits are in a better place.", objectives = "Use the Shado-Pan Torch on 20 Palewind Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30779] = { id = 30779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaying the Scavengers", description = "The rotting corpses are attracting hyena scavengers.\n\nIn addition to spreading diseases from feeding on the dead, the feral creatures will attack us on sight.\n\nGo and eradicate the beasts. It is unfortunate, but ultimately for the best.", completion = "Thank you, {name}. It was an unpleasant task, but it had to be done.", objectives = "Kill 8 Ashfang Hyenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30780] = { id = 30780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemic Research", description = "As we entered the village, I couldn't help but notice yaungol totems lying around this camp.\n\nI have a suspicion that there are dark forces at work here, and those totems may be the key to drawing them out.\n\nCould you bring me some of these totems for further inspection? I would like to study them.", progress = "I do believe the totems could be of use to us.", completion = "I was right! These totems were once used to store and conduct immense magical energies.\n\nI do believe I can use them once again to do the same.", objectives = "Collect 9 Palewind Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30781] = { id = 30781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Toll of the Yaungol", description = "Ban has asked me to explore the village to determine what happened here.\n\nI noticed smoke rising up from the east, the west, northwest, and the south.\n\nI need someone I trust to watch my back.\n\nWhat do you say? Want to help me on my first scouting mission?", progress = "Something terrible must have happened here.", completion = "Thank you for your help, {name}.\n\nWe cannot know exactly what happened here, but it's clear that something caused the yaungol to turn on one another.\n\nWhat kind of power could do this?", objectives = "Take Xiao Tu to the smoke trails at Hatred's Vice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30782] = { id = 30782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Spirits", description = "The spirits of the fallen villagers have risen! I can feel the hatred emanating from the spirits.\n\n{name}, if we are to survive here, we must defend ourselves. This is the only way we can put them to rest.", progress = "The air is thick with their malicious intent.", completion = "Well done. We cannot bring them retribution, but at least we can end their rage.", objectives = "Kill 10 Spiteful Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30783] = { id = 30783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred Becomes Us", description = "I should have suspected a sha presence earlier!\n\nWe are safe as long as we stand inside the Totem of Harmony's protective wards, but many of our people were not so lucky.\n\nThey were trapped outside the camp when the sha's powers manifested, and now they turn upon each other!\n\nTake one of my totems with you. Place the totem near a crazed ally to purify them, but beware.\n\nYou may have to face the darkness that gripped them.", progress = "Our people are possessed by hatred. We must help them come to their senses!", completion = "Thank you.\n\nThe sha preys upon the weak and the vulnerable.\n\nIf we are not vigilant, even the strongest of us can succumb to the sha's dark influence.", objectives = "Use the Totem of Harmony to exorcise sha spirits from 8 Crazed Shado-Pan Rangers. Defeat the Seething Hatreds to purify your allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30784] = { id = 30784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Point of No Return", description = "One of our rangers reported seeing Suna up the hill to the northwest.\n\nI am relieved to find her safe. I had feared what she would do in her grief.\n\nWould you go speak to her on my behalf?\n\nTake this totem with you. If you encounter any danger along the way, you may find it useful.", progress = "If I could change the past, I would. If I could take Lin's place, I would.\n\nIn a thousand lifetimes, I will never be able to repay Suna's loss, or share even a measure of her grief.", completion = "What? She was possessed by the Sha of Hatred?\n\nNo. NO!\n\nDespite our differences, she was one of us. Today, the Shado-Pan has lost a dear sister.\n\nHer death will not be in vain. I will not rest until I have defeated the Sha of Hatred!\n\nSuna, I swear this to you!", objectives = "Find Suna Silentstrike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30785] = { id = 30785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gao-Ran Battlefront", description = "With your help, we have quelled the spirits of this place.\n\nAt last, they may rest in peace.\n\nOur journey into this cursed land, I am afraid, has only begun.\n\nI have some important matters to finish up here, but we will be moving out soon.\n\nI need someone to go ahead and tell Lord Taran Zhu that we are joining him.\n\nFind him at the Gao-Ran Battlefront. Tell him what has transpired here.", completion = "Did the northern expedition go well, then? What news do you have to report?", objectives = "Speak to Lord Taran Zhu at the Gao-Ran Battlefront in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30786] = { id = 30786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spear Through My Side, A Chain Through My Soul", description = "My fate is sealed. The yaungol put this spear in my side. The wound will kill me.\n\nThe yaungol hold me in place with their twisted, corrupted magic. The indignity of it hurts worse than my spear-wound.\n\nMy death, I cannot stop. My imprisonment... you may be able to help me with this.", progress = "I will not die before having my revenge.", completion = "I am freed.\n\nThe yaungol must be stopped.", objectives = "Slay Dmong Naruuk, the shaman who holds Orbiss hostage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30787] = { id = 30787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Torches", description = "Until recently, the yaungol shaman would come here to work alongside us. Now, they bend my people to their will.\n\nIf we refuse, they kill us. Even if we oblige... they kill us.\n\nThe yaungol mist-shaman's magic flows through his torch. Take his torch away, and he has nothing.", progress = "I can use these torches in my revenge.\n\nI have not succumbed to this wound yet. I can still have my revenge before I die.\n\nThere is time yet.", completion = "This torch... the yaungol once used these to communicate with me, with my people.\n\nNow, they use them to undo us.", objectives = "Obtain 6 Mist-Shaman's Torches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30788] = { id = 30788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgoss", description = "The leader of the yaungol mist-shaman is named Jahesh. He is known for his strength.\n\nOne of my kind is also known for his strength. His name is Golgoss.\n\nGolgoss sleeps within the mists of the Upper Sumprushes. Help me to summon him, and he will join me in avenging our people.", progress = "Golgoss is no coward. He will relish the opportunity for revenge.", completion = "Golgoss does not speak your language, other than a few words. I suppose I am unique in this regard.\n\nHe thanks you for summoning him.", objectives = "Summon Golgoss by planting the Mist-Shaman's Torches into the Peat Clump in the Upper Sumprushes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30789] = { id = 30789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconiss", description = "If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have Arconiss by my side. Arconiss' ferocity is second to none.\n\nHe rests beneath the mists of the Upper Sumprushes. Find his resting place, and then use these torches to awaken him.", completion = "It will be difficult to lose with Arconiss by my side.", objectives = "Summon Arconiss by planting the Mist-Shaman's Torches into the Peat Mound in the Upper Sumprushes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30790] = { id = 30790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgoss Hungers", description = "Golgoss' strength is great, but he requires nutrition before he can use it.\n\nThe snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These should sate his appetite.", progress = "Golgoss' hunger is great.", completion = "We are one step closer to my goal.", objectives = "Obtain 10 Snarlvines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30791] = { id = 30791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconiss Thirsts", description = "Arconiss fights with unmatched fury, but his extended stay beneath the mists has left him weakened.\n\nThe rodents of the swamp are plentiful, and their bodies are filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.", progress = "Our preparation will not take much longer.", completion = "Yet another step closer to completing my mission.", objectives = "Obtain 4 Clotted Rodent's Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30792] = { id = 30792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orbiss Fades", description = "I knew death would come. I did not know that it would come this fast.\n\nI must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is nutritive to my kind.\n\nGather this mist however you can... in jars, in vials, within the interior of your bags. Bring it back to me, and I can use it to remain corporeal for a bit longer.", progress = "I require more mist. I am fading...", completion = "I told you earlier, this wound would be my death. While you have bought me a bit more time, it is not long now.", objectives = "Obtain 8 Gushing Mists by walking through mist geysers in the Upper Sumprushes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30793] = { id = 30793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists' Opportunity", description = "Now is the time to strike.\n\nGolgoss, Arconiss, and I will go east, into Jahesh's domain. Meet us there, and prepare for battle.\n\nToday, we restore the pride of our people.", completion = "My name will be forgotten, but my actions will not.\n\nNor will yours, {name}.", objectives = "Slay Jahesh of Osul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30794] = { id = 30794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Care", description = "I... am alive... but barely. They killed the rest. My friends... and family...\n\nI must return to the village... But, I do not have long, and cannot move on my own... are you a healer? I... have a healing potion in my hut... search my belongings. You can use your magic, if you have it.", completion = "Thank you. I suppose... I'll need to ask you to do a bit more before I can return to the village. I cannot leave the bodies of my friends and family here.", objectives = "Heal Sage Liao to get him back on his feet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30795] = { id = 30795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staying Connected", description = "The Tongue of Ba-Shon should allow us to communicate from long distances, {name}.\n\nIf the relic works the way I think it will, I should be able to stay here and continue my meditations while you do some scouting in the Valley of Emperors.\n\nMishi will take you to the edge of the valley so that we can test my theory. I would hate for you to be in the tombs with no way to contact me. That would be horrible!", completion = "Very good! The relic works!\n\nIt appears there is more going on in the Valley of Emperors than I had anticipated. It is crucial we figure out why the Mogu are opening the tombs.", objectives = "Use the Tongue of Ba-Shon in the Valley of Emperors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30796] = { id = 30796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to Everything", description = "These spirits must have been released when the tombs were opened... \n\nDeath was not final for the Mogu. Instead, death was merely a stop over on the path to a new body. Spiritbinders used a foul magic to transfer spirits from one shell to the next.\n\nYears of being trapped in the tombs has left them confused. They need to be destroyed before their confusion turns to anger or worse, they find a new shell.", progress = "Have you disposed of the spirits yet?", completion = "You have done them a great service, {name}.\n\nIt is a cruel fate to be stuck between the living world and the afterlife.", objectives = "Destroy 5 Tormented Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30797] = { id = 30797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Was Almost Alive", description = "A ritual took place here, and from the looks of it wasn't successful.\n\nAmong the abandoned items a book lies open. The text on the pages is foreign to you.\n\nCarrying the whole book may be difficult, but a single page might be enough. If you can get the page to Lorewalker Cho he may be able to tell you what it says.", progress = "What have you found, {name}?", completion = "This text is curious indeed, {name}...\n\nIt appears to have been written in the Meng dynasty, but some of the symbols are wrong. I don't think the Mogu wrote this, although it is oddly close.\n\nIt will take me some time to translate. Keep moving and see if you can find anything else.", objectives = "Tear a page from the open book to give to Lorewalker Cho.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30798] = { id = 30798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Emperor's Shield", description = "The Mogu have been scattered and sparse in number for many years. Their purpose in the valley makes sense now.\n\nWith this many restless spirits they can build themselves an army using the guardians buried in each tomb. Combined with the Zandalari forces this would be devastating!\n\nThe Tomb of Secrets houses elite warriors called the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest rise to the southwest.", progress = "Have you gone to the Tomb of Secrets yet?", completion = "The Mogu and the Zandalari intend to resurrect the Thunder King?!\n\nWe cannot let this happen, {name}! The Thunder King will rain destruction on this land with his return.", objectives = "Stop the Spiritbinding Ritual in the Tomb of Secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30799] = { id = 30799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tomb of Shadows", description = "Given the artifacts you found on the altar, I would guess they were attempting to perform a Spiritbinding ritual.\n\nMost of the texts involving Spiritbinding were locked away in the Tomb of Shadows. Perhaps we will find the answers we seek there.\n\nLook for anything that might help us. You'll find the tomb on the first rise closest to the ritual altar.", progress = "Did you find anything in the Tomb of Shadows?", completion = "These tablets recount the history of the Mogu and Zandalari alliance dating back to the time of the first Mogu emperor.\n\nBy the looks of things they have rekindled their alliance. But why now?", objectives = "Collect a rubbing of the Shen Dynasty Tablet, the Wai Dynasty Tablet, and the Qiang Dynasty Tablet in the Tomb of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30800] = { id = 30800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Their Thunder King", description = "Our only hope is to find the Thunder King's remains before they do. He must be buried within the Tomb of Conquerors.\n\nGetting to his remains will not be easy, {name}. The tomb will no doubt be defended by guardians and other unfriendly surprises intended to ward off thieves.\n\nOnce inside we will need to figure out where his remains have actually been placed.", progress = "Have you figured out where the Thunder King's remains are hidden?", completion = "We are fortunate they haven't gotten to Lei Shen's remains... yet.\n\nThe Zandalari will not give up until they have what they want.", objectives = "Find the Bottom Fragment of Lei Shen's Tablet and restore the Tablet of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30801] = { id = 30801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons from History", description = "The Thunder King was a vicious Emperor and with the Zandalari at his side he was unstoppable. His return would surely return this land to turmoil and misery.\n\nYou must locate his remains and take them somewhere safe. The Tablet of Thunder should help you figure out how to access his tomb.", progress = "Have you read the tablet?", completion = "They will need to move the remains to a secure location. We must go after them!", objectives = "Read the Tablet of Thunder in the Tomb of Conquerors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30802] = { id = 30802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing the Storm", description = "We need to figure out where they are taking the Thunder King's remains. It won't be possible for them to resurrect him in the Valley of the Emperors. They would need to be somewhere remote and secure.\n\nIt appears that getting out of here may also prove to be a challenge....\n\nFight your way out and look for information concerning the location of the remains.", progress = "Were you able to find any information on their location?", completion = "This is dark Zandalari blood magic. Once we're done with the map it should be burned.\n\nThe map indicates they have headed for the coast just outside of a tiny fishing village called Zouchin. The villagers there may be able to help us find the Zandalari. We just have to hope the village is still standing...", objectives = "Find the Blood-Revealed Map on a Zandalari Warrior.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30804] = { id = 30804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fearmaster", description = "I am not gonna take this anymore. My wife, bless her, poured her heart and soul in to that ranch making it what it is today.\n\nThem yaungol got a leader over there being all smug and what not. I'll pay you handsomely if you knock that smug smile off his filthy, stinking, good for nothing face.", progress = "So many strangers in these lands these days. Luckily you {class} seem to be all right.", completion = "Yee haw! I knew you humans might be good for somethin'. He must of made a very satisfying \"thump\" when he hit the ground.", objectives = "Kill the Fearmaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30805] = { id = 30805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice", description = "After the mercenaries robbed us, most left.\n\nBut one of them... after the others took all we had, he ran the rest of us through. For sport!\n\nGet justice for the fallen. Perhaps news of their death will raise my spirits enough to go on.\n\nYou'll find them just west of here.", completion = "Ahh.. they are dead. Already, I can feel my spirits lifting. Soon I will have the strength to return to the village.", objectives = "Kill Captain Ripflesh and 6 Blackmane Mercenaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30806] = { id = 30806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Life", description = "Many have perished here. We will need to honor them properly, which means gathering the makings of incense of life. \n\nIt doesn't just smell nice - it has restorative properties, and can even help plants grow. Maybe I can get a whiff of the ingredients to get me back on my feet.\n\nThe materials can be found on creatures around here - except for the spices, which were stolen by the mercenaries who pillaged the village.", progress = "Are those the ingredients for Incense of Life I smell on you? Or... perhaps you haven't bathed recently.", completion = "Beautiful, beautiful. Better to not need to bury our friends, but if we must, it is good they will have a fitting ceremony.", objectives = "Gather an Opalescent Blue Crab Shell and 8 Stolen Pandaren Spices.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30807] = { id = 30807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Falls, For the Fallen", description = "I do not wish to dishonor my friends and leave them in unmarked graves.\n\nYet, we have never needed to bury so many at once, and I am in no condition to gather materials.\n\nPlease, visit the lakes that hug the mountains edge along the road to the south. Underneath the waterfalls there, you will find stones that have been polished to a sheen by the falling water. They will make suitable headstones.", progress = "The stones - have you brought them?", completion = "Good. Thank you. After this, I cannot imagine leaving my fellows to less than a proper burial.", objectives = "Gather 3 Waterfall-polished Stones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30808] = { id = 30808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grummle's Luck", description = "The yaungols stole our luckydos! Mean riders with spears took them from our caravan of brothers coming down the Burlap Trail.\n\nThis is very bad fortune. If the yaungol discover the secrets of luckydos all grummles will be in big trouble.\n\nRecover our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.", progress = "A luckydo is a thing of much good fortune. Yaungol know nothing of how to use luckydos... yet.", completion = "Hurray! Our Luckydos. Many thanks and fortune to friend of grummles!", objectives = "Find 8 Stolen Luckydos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30814] = { id = 30814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foot in the Door", description = "<Lord Taran immediately pins you down with his steely gaze.>\n\n{class}, you bear the marks of many a past battle.\n\nGood! We need more seasoned people like you to hold back the front.\n\nWe've managed to secure a foothold here, but the yaungol are desperate to remove our presence.\n\nIf you wish to prove your worth, go down the hill and show the yaungol that we will not back down.", progress = "We are slowly gaining ground.", completion = "Good. I can see that you are capable.\n\nI hope to rely on your talents for what is to come.", objectives = "Kill 8 Osul Chargers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30815] = { id = 30815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Death of Me", description = "I have resolved to remove this spear from my side.\n\nFor this, I require your assistance. Your grasping hands are stronger than mine.", completion = "By removing this spear, I have truly guaranteed my own death.\n\nThis does not frighten me.\n\nI would sooner die than live carrying the weapon of my enemy.", objectives = "Remove the spear from Orbiss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30816] = { id = 30816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Checking In", description = "When the trolls came, they brought their mercenary... friends with them. I saw them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there - can you check in with him and make sure he and his village are well?", completion = "Ahh... My cousin is wise to be worried... I am not well...", objectives = "Check on Sage Liao at the Zaochin Strand in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30817] = { id = 30817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Healing of Shen-zin Su", description = "This is what comes of such recklessness. How could he think this was even a possibility?\n\nNevermind, there's no time for that now. We need to act to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", objectives = "Rescue and defend healers until Shen-zin Su's wound is healed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30818] = { id = 30818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Fate", description = "{name}, I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", sourceObjective = "Return to the Temple of Five Dawns. A cart is waiting near the Skyfire Crash-Site to take you there.", sourceObjectiveStatus = "unverified-source-field" }
quests[30819] = { id = 30819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing the Remains", description = "Thank you much, friend. After this tragedy, it is good that fortune has smiled on us and sent you.\n\nYou have gotten justice for my fallen friends, and gathered the necessary materials to honor them. I will gather their bodies, prepare the materials for their funerals, and meet you at the graveyard. \n\nIn the meantime, however, please return to my cousin and ask him to gather the villagers for the funeral.", completion = "I see... it is tragic what has happened there. We will meet you at the graveyard to honor them.", objectives = "Return to Li Hai and tell him about the funeral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30820] = { id = 30820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Funeral", description = "As I said, I will gather the town - we will be at the funeral. \n\nAs the one who has done so much to honor our friends, we feel it is only right that you will be the one to light the Incense of Life and usher their spirits to the life beyond.", progress = "You must light the incense to honor the dead.", completion = "Good. Let us begin the funeral.", objectives = "Attend the funeral and light the Incense of Life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30821] = { id = 30821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Grind", description = "Alright, it's time to take Kota Kon out for her \"walk.\"\n\nWe brewed two fresh pots of kafa just for her and she's all fueled up!", progress = "Kota Kon's waiting for you! She won't let anyone else ride her.", completion = "Hah hah! We could hear those monkeys screamin' from over here!\n\n<Burrberry turns to Kota Kon.>\n\nWho's a pretty girl? You are!!", objectives = "Speak with Kota Kon at Kota Basecamp to ride her, then kill 100 Hozen along The Burlap Trail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30823] = { id = 30823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shut it Down", description = "My cousin over at Kota Basecamp mussed up. He mussed up bad.\n\nHe was too lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up and give back the seeds... in a day or so.\n\nHe fed everything he had to the goots on Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?", completion = "Thank you for helping to correct my mistake, friend. Let this be a lesson to you: never feed the goots.", objectives = "Kill 12 Kafa-Crazed Mountain Goats on Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30824] = { id = 30824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gourmet Kafa", description = "It was a crazy idea: kafa berries go in the goot, seeds come out.\n\nKafa'kota is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is GOURMET.\n\nBut it's over now. Uncle Keenbean is upset and peak is a muss. All that's left is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it easily when the mountain is safe again.", completion = "I'd heard an adventurer was up there marking the deposits. Mussy work for someone with your skills, but I appreciate it.\n\nI'll get up there and... harvest them soon.\n\n<Cousin Gootfur begins wrapping long strips of linen around his hands.>\n\nCan't believe I thought this was a good idea.", objectives = "Mark 15 Kafa'goot \"Deposits\" on Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30825] = { id = 30825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kota Blend", description = "Kota Peak is famous for its kafa bushes - no other can survive at this elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to our cousin. He's got the wildlife up there hooked on kafa with his scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves.\n\nUncle Keenbean will pay you good for any berries you bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.", objectives = "Collect 100 Kafa'kota Berries from Kota Peak. They can be found in bushes growing on the mountainside or piled up in the yeti caves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30826] = { id = 30826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Brewing", description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat goots.\n\nThen stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and the yeti ate them goots.\n\nNow they're moody, cranky, sleep a lot but never seem rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come lookin' for more kafa.\n\nThen we all in trouble.", completion = "Ah, hello there! Tallmug sent a messenger yak over explaining that you would be helping us with our yeti problems.\n\nAnd you weren't torn to shreds! Yeti's are tough enough on their own - can't imagine what a cranky kafa-addict yeti must be like. You're brave. Or lucky. Or dumb.\n\nMaybe all three.", objectives = "Kill 5 Kafa-Crazed Yetis in the caves on Kota Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30827] = { id = 30827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lies Beneath", description = "If my suspicions are correct, this place still reels from some lingering darkness.\n\nWhatever happened here... it could not have been the natural course of events.\n\nEven the yaungol are not so brutal as to slaughter their own kind to the point of... this.\n\nI will use the totems that you brought me to perform a cleansing ritual.\n\nI need someone to assist me in the ceremony. Let me know when you are ready.", progress = "I believe that we must drive the taint from this place.", completion = "We look upon the true face of hatred!\n\nNow it all makes sense. This is the work of the sha.", objectives = "Speak to Yalia Sagewhisper to begin the ceremony.\n\nThen, activate the Totem of Kindness, the Totem of Tranquility, and the Totem of Serenity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30828] = { id = 30828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Mere", description = "Pools of the same murky substance that came out of Mei emerged in the lake recently.\n\nI will travel into the Mere with you. Point out the pools of corruption that you are ready for me to cleanse.\n\nYou will need to deal with whatever comes out and protect me as I complete the ritual.", progress = "Is the lake cleansed?", completion = "The Mere... I can feel the corruption clearing. At least now, this corruption will not spread.\n\nBut, there is one more thing we must do.", objectives = "Point out Pools of Corruption in Inkgill Mere to Waterspeaker Gorai to let him know you are ready to defend him while he completes the cleansing ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30829] = { id = 30829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tongue of Ba-Shon", progress = "I'll need to bind my essence to the Tongue, then you can use it to speak with me from anywhere.", completion = "This must be a very powerful relic for Zuan to want it back so badly.\n\nIt frightens me to think of what else they may find in the tombs...", objectives = "Assist Lorekeeper Cho in performing the Binding of Ba-Shon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30834] = { id = 30834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Father and Child Reunion", description = "They survived? My father is alive!\n\nI thought we would all die here in this horrible mere, at the hands of these insane Jinyu.\n\nI will find my way back - meet me back at camp.", progress = "My boy! He is alive!", completion = "You found him! This is all I have to give, but in finding my son, you have more than earned it.", objectives = "Return to Merchant Shi and Wu-Peng at the southeastern shore of Inkgill Mere in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30854] = { id = 30854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lha-Po Tracking Quest" }
quests[30855] = { id = 30855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Shai Hu", description = "I can hear the voice of the Mere - it has been purified.\n\nBut, this chapter in my people's history will never be closed - not until we defeat Shai Hu.\n\nHe has retreated to the central island in the Mere, corrupting our holiest of sites.\n\nBeware - he is strong. But, after all we have done, I am confident we will be stronger.", completion = "Thank you, {name}. You have assured that this corruption will not spread, and that my people - those who have not been corrupted - will be able to live on and found a new village. \n\nOur history will live on. You have done more for us than we could have ever hoped.\n\nThank you, friend.", objectives = "Defeat Shai Hu. He can be found at the Waterspeaker's Sanctuary, the island in the center of Inkgill Mere in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30879] = { id = 30879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1: Brewmaster Chani", description = "Welcome, Challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", progress = "Without conflict, there can be no growth.\n\nThe need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", completion = "Well done, challenger.", objectives = "Defeat Brewmaster Chani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30880] = { id = 30880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1: The Streetfighter", description = "Welcome, challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with strength, fight with honor.", progress = "Without conflict, there can be no growth.\n\nThe need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", completion = "Well done, challenger.", objectives = "Defeat the Streetfighter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30881] = { id = 30881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2: Clever Ashyo & Ken-Ken", description = "You may know your next challengers. They were arguing fiercely when they arrived, so I have charged them with fighting side by side.\n\nThis will teach them the strength of friendship, and possibly entertain me in the process.\n\nGo to the north eastern arena and face this jinyu and hozen.\n\nDo not be gentle, they need to learn to work together.", progress = "Strength can come from an ally as much as from one's self.", completion = "Pity that those two did not learn their lesson yet. No matter. In time I am sure they will come to see wisdom.\n\nIn the meantime, congratulations on your victory.", objectives = "Defeat Clever Ashyo and Ken-Ken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30882] = { id = 30882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2: Kang Bramblestaff", description = "Your next challenger is a Bramblestaff. Strength is in their blood. I remember a full century of only Bramblestaff champions.\n\nNo pressure, little {race}.\n\nGo to the eastern arena north of here and face this young challenger. See first hand if strength is earned or inherited.", progress = "I was once defeated in a match by a Bramblestaff. In my defense, he distracted me with a ball of yarn.", completion = "Ah. The Bramblestaff family have long held the championship generation after generation. I am sure this one will take the title sooner or later as well.", objectives = "Defeat Kang Bramblestaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30883] = { id = 30883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3: The Wrestler", description = "Your next challenger is a favorite of mine. He draws strength from raw force and determination.\n\nPlus he has a mask.\n\nFace him in the western arena when you are ready, and good luck.", progress = "Sometimes strength can come from the outside.", completion = "Well fought, challenger. That was a fierce opponent.", objectives = "Defeat The Wrestler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30884] = { id = 30884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Battlefront", description = "This battlefront has been undermanned and unsupplied for too long during my absence in Kun-Lai. We need to get things back in order here before we can pick up the trail of the Sha of Hatred.\n\nTaoshi is my best. I've sent her north to investigate rumors of mantid that have somehow made it through the battlefront. I need someone I can trust to get out there and work with her to plug any holes in our defenses.\n\nIf my reports on you are correct, I can trust you with this, right {class}?", completion = "You look capable. Taran knows to send me the best. I like that.", objectives = "Meet with Taoshi at Dampsoil Burrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30885] = { id = 30885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3: Master Boom Boom", description = "Your next challenger found his strength on a beach. Particularly in a box labeled \"dynamite.\"\n\nHe proves however that found strength can be as deadly as personal strength.\n\nWhen you are ready, face this Master Boom Boom in the Western Arena.", completion = "Well fought, challenger. That was a fierce opponent.", objectives = "Defeat Master Boom Boom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30886] = { id = 30886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Example Pandaren Race Quest" }
quests[30887] = { id = 30887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Intruders", description = "Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep them out of eastern Townlong Steppes. If we allow them north of the barricade, we may lose our foothold here.\n\nLet's clear them out. I'll be with you.", completion = "This is where they're getting through, the eastern pass.", objectives = "Kill 12 Krik'thik Deep-scouts with Taoshi's help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30888] = { id = 30888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach in the Defenses", description = "Normally, it only takes a few scouts to hold this pass. Most of this territory is in sight of the wall, so archers would devastate any mantid force attempting to push through here. The problem is, most of the archers are occupied with the onslaught at the gate.\n\nTake this flare - it will help you locate the mantid that are sneaking through the eastern pass under our diminished watch. Kill any you find. We can't let them lay a trail that might lead the mantid swarms farther into the steppes.", progress = "The defenders on the wall are stretched thin. The Yaungol are pushing through the gates to Kun-Lai in the north. The mantid are pouring against the gates to the Vale of Eternal Blossoms. I hear that there's been a breach into the Valley of Four Winds in the south too.\n\nWe do not have the men to combat all of these threats.", completion = "There are more getting through than I thought. I may need to stay here and clean up a while.\n\nYou've done more than your part though, {class}. Thank you.", objectives = "Use the Shado-Pan Flare to aid in killing 10 Krik'thik Scentlayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30889] = { id = 30889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trap Setting", description = "Good to meet you, {class}. We have traps all along the pass to help us catch mantid that might be sneaking through, but their numbers have been so great that most of the traps have already been triggered.\n\nTaoshi said you might be able to reset some of them while you're out there. Can you help?", progress = "These traps have been very effective, the mantid numbers are just getting out of hand in these past weeks.", completion = "We could use a few more capable men like you around the camp. Thank you for your help, {class}.", objectives = "Rearm 8 Shado-Pan Spike Traps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30890] = { id = 30890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Watch", description = "I'm being told that our scouts have been on duty in Shallowstep Pass for more than 2 days straight, no rest. No wonder mantid are slipping through. Even the most dedicated scouts would slip with those kinds of shifts.\n\nI want you to go out there and deliver orders to the scouts that they are to return to the battlefront immediately for rest and rations. I'll arrange for a new shift to be posted.", progress = "This whole battlefront is being worked to the bone. We need more men out here.", completion = "Thank you. I'll have the new scouts at their posts shortly.", objectives = "Deliver return orders to Scout Wei-Chin, Scout Long, Scout Ying, and Scout Jai-Gan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30891] = { id = 30891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treatment for the Troops", description = "A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan fighting.\n\nThe mantid have poison that chews through the skin and infects the blood. It makes for a slow, excruciating death when not treated.\n\nI need pollen from the violet citron flowers. The nearest place to find them is around Dampsoil Burrow just north of the battlefront. If you happen to go in that direction, could you bring some back for me?", progress = "Mixed properly, the pollen from these flowers can eat away at the poison without doing any lasting damage to the body otherwise.", completion = "Marvelous. And in good condition too!\n\nThank you, kind {class}.", objectives = "Collect 10 Violet Citron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30892] = { id = 30892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back on Their Feet", description = "{name}, I could use your help. With their long shifts, our warriors down at the southern front of the battlefront are fighting to the point of exhaustion, and many of them have been exposed to the mantid poison.\n\nWe need more people to tend to the wounded. I've prepared some bandages with the herbs you brought me, but if you have some healing skills, those might work even better.\n\nPlease, {name}, get our men back on their feet so that they can get back here to safety.", progress = "With the constant mantid attacks, the men are being worked to the bone. We are undermanned on all fronts.\n\nYour help means a lot to us, {name}.", completion = "There are several warriors that owe their lives to you. You have my deepest appreciation, {class}.", objectives = "Heal 8 Injured Gao-Ran Blackguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30893] = { id = 30893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Swarm", description = "Gao-ran's men need help down on the southern front. If you want to stand by the Shado-Pan, that's where you should do it.", completion = "The men of the battlefront are growing to respect you. You clearly know how to fight.", objectives = "Kill 12 Krik'thik attackers at the Gao-Ran Battlefront.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30894] = { id = 30894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rummaging Through the Remains", description = "I do have another task for you, {name}, though it's a might grim. I really need to get to the bottom of this mantid poison, but to do that, I need more information directly from the source.\n\nWhile you're down on the southern battlefield, could you bring me back some mantid limbs so that I can examine their intact poison glands.", progress = "I'm hoping to find a permanent counter to the mantid poison so that the men won't be afflicted in the first place. It may take some time to piece it together.", completion = "These are in great condition! Thank you, {name}!\n\nYou know, I've managed to distil some of their poison into a form that we can apply readily. I've even come up with some methods for weaving it into spell-casting, if you believe it. Would you like to give some a try?", objectives = "Recover 20 Krik'thik Limbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30895] = { id = 30895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improvised Ammunition", description = "I've got another job for you.\n\nThe dragon cannons we depend on to keep the thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed an improvised explosive that's made from the globe seeds down the western ridge.\n\nThey dispatched a couple initiates to bring some back hours ago, but have heard nothing from them. I want to send someone a bit more capable to make sure that this gets taken care of.\n\nAre you my <man/woman> for this?", progress = "Back even more quickly than expected. Did you bring the seeds?", completion = "It's good to have a {class} that I can count on.", objectives = "Recover 16 Volatile Dread Orbs from the Ambermarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30896] = { id = 30896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieves and Troublemakers", description = "I can't catch the little buggers for the life of me.\n\nKill any you can get your hands on. And keep a close eye on your valuables, they like to steal anything that isn't tied down.", progress = "I haven't hated plants so much since my job back at Halfhill.", completion = "I guess you're a bit faster than me. Well, thanks.\n\nI'll try to finish collecting some orbs and get them back to camp while there's still some face to save.", objectives = "Kill 10 Agitated Nettleskins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30897] = { id = 30897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Wrong Hands", description = "Look... um... this is really embarrassing. I set down my sword for like ONE SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and bounded off down the western gap.\n\nI can't go back to camp without it. Losing your weapon is a sure way to get kicked out of the Shado-Pan. It's sacred.\n\nPlease, can you try to find this big sprite and get my sword back? It would mean a lot to me.", progress = "My mom warned me this was going to happen...", completion = "You... you are a lifesaver! Seriously.\n\nThank you so much!", objectives = "Recover Initiate Chao's Sword.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30898] = { id = 30898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting the Swarm", description = "The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use.\n\nGet down on the battlefront and man one of the cannons. Let none through.", progress = "I can't remember the last time they swarmed this thickly. They probably haven't within my lifetime.", completion = "We're not done yet...", objectives = "Use a Dragon Launcher to kill 50 swarming mantid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30899] = { id = 30899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Skilled Hands", description = "{name}, take these crossbow bolts and then bring them to Hawkmaster Nurong at Farwatch Overlook to the southwest.\n\nNurong is praised among all the Wukao for being a flawless shot. His efforts are credited with holding the line here for these many months. I'm hoping you can work with him and judge for yourself. He may be the final Shado-Pan we need for the hunt.", progress = "Another wave of fliers approaches. Be ready.", completion = "There's a lot of movement on the other side of the chasm... something big is coming.", objectives = "Bring the Shado-Pan Crossbow Bolt Bundle to Hawkmaster Nurong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30900] = { id = 30900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of the Dread Wastes", description = "That thing is huge!\n\nThe Shado-Pan holding the battlefront were never trained for something like this... let's get down there and take it out ourselves.", completion = "You. You're coming with me.\n\nI've never seen someone handle themselves on the battlefield like that. I need a strong {class} like you with me when we face the Sha of Hatred.", objectives = "Defeat Norvakess, the Terror of the Dread Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30901] = { id = 30901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along the Southern Front", description = "I'm heading westward with Taoshi to gather the strongest I can find to confront the Sha of Hatred.\n\nI would like you to come with me.", completion = "Let's get this taken care of so we can get down to the bridge.", objectives = "Ride with Taran Zhu and Taoshi to Dusklight Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30902] = { id = 30902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 4: Master Windfur", description = "Well done, challenger. You have reached the final round.\n\nYour last opponent is a powerful master of the winds. He has defended his people for many years and stood as champion on more than one occasion.\n\nFace this Master Windfur in the main arena when you are ready.\n\nAnd challenger... good luck.", completion = "Congratulations, champion! The day is yours.", objectives = "Defeat Master Windfur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30907] = { id = 30907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 4: The P.U.G.", description = "And now the final round. I have selected three challengers for you to face. This may seem unfair... to a weakling. You are not a weakling, correct?\n\nGo to the main temple, stand in the grand arena, and face these three challengers. Prove you are stronger than their combined power!\n\nGood luck, Challenger!", progress = "Some find strength in numbers. I respect this idea, when it is properly executed.", completion = "Superb! What a battle!\n\nYou have proven yourself champion of this day's tournament. Well done!\n\nYou must return and put on such a show of strength in the future.", objectives = "Defeat Hackiss, Healiss and Tankiss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30910] = { id = 30910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greenstone Village", description = "Please help!\n\nWe paid some adventurers to run off all the elemental spirits and now they're back for revenge!", objectives = "Rescue all the villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30918] = { id = 30918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hui's Vengeance", description = "I am ashamed to ask, but for Greenstone's sake... might we now trouble you to face Vengeful Hui on our behalf...?", objectives = "Defeat Vengeful Hui.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30921] = { id = 30921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Motives of the Mantid", description = "{class}. You may be of assistance.\n\nThe Shado-Pan wishes to know why the mantid are attacking so violently. We have our suspicions, but we cannot be sure. Furthermore, we do not want the mantid to know that we are investigating them.\n\nThat's where you come in.\n\nI need you to kill the mantid of Kri'vess, in the north. I will lurk behind you in the shadows, and search for clues on their bodies.", completion = "The abundance of yak hair on that mantid's body suggests one thing... it came from Niuzao Temple. Our journey continues westward, {class}.", objectives = "Slay mantid in Kri'vess so Tai Ho can look for clues on their bodies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30922] = { id = 30922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Antiseptic", description = "The Shado-Pan are rare, elite, and quite expensive to train and replace. We can't afford to have any falling to a poisoned weapon or an infected cut. That's why I need you to get... something.\n\nLet me be blunt. Mushan urine is a great, natural antiseptic. They produce a large amount of it, which is lucky... because we tend to use a lot.", progress = "It's messy work, certainly.\n\nNowhere near as messy as digging graves.", completion = "Your messy work may have saved a few lives today, {race}.", objectives = "Obtain 5 Full Mushan Bladders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30923] = { id = 30923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set the Mantid Back", description = "Every day, the mantid build up munitions for use on their enemies. We cannot stop them, just you and I... but we can set them back.\n\n<Tai Ho hands you some explosives.>\n\nI need to keep a low profile. Would you do the honors?", progress = "The Shado-Pan are counting on you, {name}.", completion = "We are in your debt, {race}.", objectives = "Use Gunpowder Casks to explode the Kri'thik Weapons and the Kri'thik Supplies in Kri'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30924] = { id = 30924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wisdom of Niuzao", description = "Niuzao, the Black Ox, rests in the temple to the west. He may know why the mantid are attacking.\n\nHe may, in fact, know much more than that.\n\nI will rendezvous with you at Niuzao Temple, {class}.", completion = "Your Shado-Pan associate has spoken with me. Yes, Niuzao knows why the mantid are attacking. But he is not ready to tell you.\n\nNot yet.", objectives = "Speak with Ogo the Younger at Niuzao Temple in the Townlong Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30925] = { id = 30925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niuzao's Price", description = "Niuzao owns a statuette which he values greatly: a small icon, in his image, sculpted by one of his long-since fallen sentinels. This statuette was recently stolen by the Sra'thik mantid, and taken to their encampment to our north.\n\nBring back this statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.", progress = "Niuzao does not move quickly, nor does he make rash decisions. Perform his task, and give him time to decide.", completion = "Niuzao will be pleased.\n\nDespite his size, our patron is a beast of grace and compassion. He treasured this icon... just as he treasures each of his followers.", objectives = "Kill the mantid of the Sra'thik Incursion so that Tai Ho can search their bodies for pieces of Niuzao's statuette.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30926] = { id = 30926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrible Truth", description = "It is with a heavy heart that I confirm your suspicions. The mantid are indeed under the sway of the Sha of Fear.\n\nIt was OUR sworn duty to confine that creature beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha escaped. It is with the mantid now.\n\nSee for yourself. The mantid burrowed into the western side of our island.", completion = "Let me make this clear... that creature was NOT the Sha of Fear. Simply a shadow... a fraction of the sha's true power.\n\nNo, the Sha of Fear is with the mantid now. The elders of my order need to be informed of this immediately.\n\nI will handle the rest from here. Thank you for your assistance, {race}. Once again, your kind proves to be an asset to Pandaria.", objectives = "Investigate the Niuzao Catacombs, then slay the Dread Shadow that dwells within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30927] = { id = 30927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Them Peace", description = "I overheard. Our secret is out, then.\n\nWhen I learned that the mantid had burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend what they could, but they were not prepared. They succumbed to fear, and never returned.\n\nA pandaren deserves to die embracing the ground, as he does in sleep... not flat on his back with his eyes transfixed in terror. Please, {name}. Give them the peace they deserve.", progress = "I should have gone with them.", completion = "Thank you, {class}.\n\n\n\nI should have been among them.", objectives = "Give peace to 10 Fear-Stricken Sentinels by closing their eyes and placing them on their bellies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30928] = { id = 30928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trail of Fear", description = "You now know Niuzao's secret. We are not only the wardens of this temple... we were the wardens of the Sha of Fear that was buried beneath it.\n\nThe Sha itself may have escaped... but it left traces behind. If you're truly going down into the catacombs, you should eliminate those traces, before they escape and cause greater problems than those we already face.", progress = "Even among our own order, only a few chosen elders knew of our sacred duty to contain the Sha of Fear.\n\nWhy they chose to tell the yak-keeper, I may never know.", completion = "We already have mantid, mogu, and yaungol to worry about. This sha problem needs to be nipped in the bud before even we are overrun.", objectives = "Kill 12 Dreadlings within the Niuzao Catacombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30929] = { id = 30929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Yak", description = "Is this the place where they replace defective yaks?\n\nCan anybody help me out, here?", progress = "This yak is not a good yak. Not at all.", completion = "I think we made a pretty convincing argument. They'll HAVE to replace my yak now.", objectives = "Help Bluesaddle replace his defective yak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30930] = { id = 30930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick a Yak", description = "I can't find a single good yak here. ALL the yaks are bad!\n\nSome are too stinky, some too fight-y, others just scared.\n\nYou look like a lucky {race}. Here, take a lasso. See if you can find a good yak for me.", progress = "See? I told you! No good yaks.", completion = "Well, well! A good yak!\n\nTell you what, {name}. I take this GOOD yak, and you can do whatever you want with this bad, bad one.", objectives = "Use the Yak Lasso on Wild Townlong Yaks, then fight against them to see if they are suitable for Bluesaddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30931] = { id = 30931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Father's Crossbow", description = "I came here to visit my dad at the temple. As soon as I got here, I saw the most terrifying thing I've ever seen.\n\nIt was a mantid, walking right past me, carrying my father's crossbow.\n\nSomething's happened to my dad! We've got to find out what it is... but first, we'll need his crossbow back. I saw him heading west, behind the temple.", progress = "Did... did you find it?", completion = "Yeah, this is dad's.\n\nLet's head on over to the temple. They'll know what...\n\n<Ku-Mo's voice catches.>\n\n...what happened to him.", objectives = "Obtain Ku-Yao's Crossbow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30932] = { id = 30932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Father's Footsteps", description = "Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any number of places... we have no shortage of enemies these days.\n\nYou're free to look around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo what he knows.", progress = "Any luck?", completion = "No shield, no crossbow, no yak... something bad has happened to dad.", objectives = "Find Father's Bedroll, Father's Shield, Ha-Cha, and Sentinel Yalo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30933] = { id = 30933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Father", description = "I've searched everywhere... but I haven't found my father. I KNOW he's alive still. He just needs his crossbow... then he'll be OK.\n\nI've heard that you Shado-Pan guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If you ever go over there, can you look for my dad?", progress = "I know he's OK.", completion = "<Ku-Mo doesn't seem to notice you.>", objectives = "Search for Sentinel Ku-Yao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30935] = { id = 30935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fisherman's Tale", description = "The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the Zandalari are hiding on one of the islands, they will know.\n\nMishi will take you as far as Emperor's Path. I will go ahead to speak with the village elders.\n\nFollow the path to Whispercloud Rise. Shin Whispercloud will help you reach the village.", progress = "The Zandalari are nearby, {name}. We must hurry!", completion = "The elders have agreed to help us figure out where the Zandalari have hidden the Thunder King's remains.\n\nThey have a few conditions though...", objectives = "Speak with Mishi to travel to the Path of Conquerors. From there find Shin Whispercloud at Whispercloud Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30941] = { id = 30941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing Zouchin Village", description = "The village elders seem to think the Thunder King's remains are being kept nearby. They have also expressed some concern with our presence here. They fear this will provoke another attack on their village.\n\nWhile our priority is in getting the remains back we cannot leave the villagers defenseless. Speak with Elder Shu and Steelbender Doshu and see what can be done to help.", objectives = "Assist Elder Shu and Steelbender Doshu in preparing Zouchin Village for battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30942] = { id = 30942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make A Fighter Out of Me", description = "Shhh! Don't speak so loudly! My father might hear you.\n\n<Shomi gestures to Steelbender Doshu.>\n\nMy father is delusional! He thinks I should be studying my tea pouring while our village is under attack. It's ridiculous! I have just as much courage as any man. I just don't know how to fight... yet.\n\nThat's where you come in. Let me travel with you! I'm a fast learner and I won't get in the way I promise!\n\nPleaseeeeee!\n\nIf we get separated I'll meet you back in the village.", progress = "I'll show my father he's wrong about me!", completion = "I told you I was a fast learner! I will head back to the village to start training others. Thank you, {name}.", objectives = "Kill 4 Amani Skirmishers, 4 Gurubashi Hexxers, and 3 Drakkari Frostweavers in Zouchin Province.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30943] = { id = 30943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handle With Care", description = "I've seen the numbers these invaders have brought with them, this will not be an easy victory. I do know of one thing that may help us gain an advantage.\n\nThere is a plant that grows around the village that can be used to make a rather effective explosive liquid. If you can gather enough I can begin brewing the mixture.\n\nThe plant you are looking for is appropriately named volatile bloom. Handle it with care, {class}.", progress = "Were you able to find a suitable amount of volatile blooms?", completion = "These are perfect! Now, I would go wash your hands a few times {class}.\n\nI would also continue to avoid open flames for a few days...", objectives = "Bring Elder Shu 50 Volatile Blooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30944] = { id = 30944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Takes A Village", description = "The villagers have been guarding Zouchin since the first attack. They are exhausted and many are injured.\n\nIf the Zandalari attack again the last thing we need is for the defenders to fall asleep on the job.\n\nRelieve them of their posts so that they might have time to heal and see their families.\n\nYou'll find them stationed around the village.", progress = "Are the villagers recovering?", completion = "Very good, {class}! With the villagers rested we may yet stand a chance against the Zandalari.", objectives = "Relieve the Exhausted Defenders from their guard posts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30945] = { id = 30945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Yours Is Mine", description = "The elders want us to mount a defense? We're not monks, {class}; we need weapons if we hope to fight!\n\nScavenge some arms from those barbarians for me. I should be able to melt them down and make something more suitable for our villagers to fight with.\n\nBring me as many as you can carry and I'll take care of the rest.", progress = "We'll need more than luck to get us through this. I hope you found something I can work with.", completion = "Well, these are better than I had anticipated! I can make four spears for every one of their blades.\n\nDon't you worry, I'll make sure the villagers are armed when the time comes.", objectives = "Retrieve 6 Stolen Weapons from the Zandalari Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30946] = { id = 30946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revelations", description = "The prisoner is being kept upstairs, {name}. It will be difficult to get information from him, but even the slightest detail about their location will help.\n\nThe elders have begun questioning him already. With their help we should be able to figure out our next move.\n\nGo speak with him and see if he has any useful information.", progress = "What did the prisoner have to say?", completion = "We cannot dwell on this setback, {name}. Prophet Khar'zul must be dealt with.\n\nEvery member of the Thunder King's forces we are able to destroy brings us one step closer to victory.", objectives = "Speak with the Zandalari Prisoner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30952] = { id = 30952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unending Siege", description = "The mantid continue to attack us. Their numbers ebb and flow, but they do not stop.\n\nIt is no matter. The yak is stamina embodied. We will not bend to them.  We will defend his home forever.\n\nWill you help us?", completion = "You fight like you are one of us.", objectives = "Defeat 12 Sra'thik attackers at Niuzao Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30953] = { id = 30953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Sentinels", description = "Our sentinels can fight for days on end, but even they have their limits. Since the mantid swarm began, too many of them have pushed themselves beyond their abilities.\n\nPlease, aid them in whatever way you can. If you are unable to heal them yourself, you may give them some of this. A mouthful of nutritious yak's milk will give them the strength they need.", progress = "Things look grim out there.", completion = "In times like these, we must trust in the power and protection of Niuzao. Should things get any worse, he will protect us.\n\nHe always does.", objectives = "Heal 8 Wounded Niuzao Sentinels above 50% health. You may use the Yak's Milk Flasks or your own healing spells and abilities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30954] = { id = 30954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade is a Blade", description = "This is no time to hold to tradition. Our masons' calloused hands bleed and tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break them.\n\nIt is time to fight smart.\n\nMany of the mantid come bearing weapons, and when they die, they simply leave them on the battlefield. It would be a shame to see them go to waste.", progress = "Our men are accustomed to fighting with maces and clubs. Unfortunatly, we have little time for customs.", completion = "I will see to it that these are properly distributed. What's more - I'll make sure our blacksmiths get a rest. Niuzao knows they deserve it.", objectives = "Obtain 10 Sra'thik Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30955] = { id = 30955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paying Tribute", description = "Our patron Niuzao is a mountain on wheels... very difficult to move, even more difficult to stop. My point: once we get him moving, the mantid will have their arms full trying to slow him down.\n\nThe easiest way to get him moving is to put food in front of him. Luckily for us, food in our temple is plentiful... even in wartime.\n\nI will send one of my strongarms with you, to shoulder the load.", progress = "Niuzao, please... it is time to join the battle...", completion = "He will get up. Soon. Maybe not today, but soon.\n\nAnd when he does...\n\n<A smile grows on Paosha's face.>", objectives = "Obtain 6 stores of Niuzao Food. Your Niuzao Strongarm will carry the food for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30956] = { id = 30956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Siege Swells", description = "Today's mantid swarm is among the worst I've seen. We are lucky to have Niuzao join us in battle.\n\nHelp him, {class}. Return to the courtyard, and join in the defense of our temple.", completion = "Look at him, {class}.\n\nNothing can stop Niuzao. Only Niuzao can stop Niuzao.", objectives = "Defeat 25 Sra'thik attackers at Niuzao Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30957] = { id = 30957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Overwhelming Swarm", description = "I command the sentinels of Niuzao. Every defender out there can hold his own against the mantid swarm.\n\nThe kunchong, however, are something different.\n\nThey are massive, violent, and without a question the biggest threat to my sentinels' lives. Only Niuzao stands a chance against them. Niuzao... and perhaps you.", completion = "Put on our armor, and you'd be indistinguishable from any of the other sentinels out there.\n\nGood fighting, {race}.", objectives = "Defeat 4 Sra'thik Kunchong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30958] = { id = 30958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Battle's Shadow", description = "Niuzao's appearance on the battlefield is a blessing... in more ways than one.\n\nWith the distraction that he's caused, our stonemasons have seized the opportunity to build up our crumbling walls. They could use your help.\n\nToss any loose bricks you find up their way. And hurry! Niuzao will not rampage forever.", completion = "It looks like the walls are beginning to take shape again. In time, the Temple will be whole again.", objectives = "Throw 10 Loose Stones up to Niuzao Stonemasons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30959] = { id = 30959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Guns", description = "The mantid now surround the Temple with their infernal war wagons. The sooner we are rid of those things, the better. You could destroy them with your own weapons and spells, but this will work much faster.\n\n<Ogo hands you a few small casks of hastily-packed explosives.>\n\nBeware of retaliation from mantid that remain be inside the war wagon when it explodes. In fact, I'd stay as far away from those things as possible.", progress = "We can push these mantid back. We can outlast them.", completion = "Good, you're back in one piece.\n\nWe hope to be seeing more of you in the future, {race}.", objectives = "Destroy 3 Sra'thik War Wagons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30960] = { id = 30960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning from the Pass", description = "I still have some cleanup to do here in the pass - there are some mantid still making it through. You're a valuable person to have at hand though, and I know Taran wouldn't appreciate me keeping you longer for such basic work.\n\nTaran should still be in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.", completion = "Welcome back. I heard about the breaches in the eastern pass. It sounds like I put the right people on the job.", objectives = "Report in to Taran Zhu at the Gao-Ran Battlefront.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30961] = { id = 30961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savior of the Inkgill", description = "I will go now to return to my kinsmen. Please visit us back at the southwestern edge of the Mere, so that we may thank you.", sourceObjective = "Speak with Waterspeaker Gorai at the southwestern edge of Jinyu Mere.", sourceObjectiveStatus = "unverified-source-field" }
quests[30963] = { id = 30963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field Armorer", description = "The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and burned. And it's my job to repair it.\n\nI'm no armorer, but I can repair a broken piece of mail as long as the hole's not too big.\n\nI prefer to use shell fragments from the tortoises that live in the wild fields to the northeast. Get some for me, and I can keep more Shado-Pan armored and alive.", progress = "I refuse to let one of our kind fall just because of a broken set of armor.", completion = "Excellent. I'll get to repairing the armor tonight, once most everyone's returned.", objectives = "Obtain 120 Rankbite Shell Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30964] = { id = 30964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Poultice", description = "A dry bandage doesn't do much good, other than maybe keeping bugs out of the wound. In some camps, that's the best you can hope for.\n\nNot in my camp, though.\n\nI prefer to make a paste from whatever soothing herbs I can find, and layer that between bandages. The most soothing herbs I've been able to find in the field are the Mao-Willows from the fields in the northeast. If you run into any, bring them back.", progress = "Any luck out there, {name}?", completion = "These will do.\n\nThe Shado-Pan appreciates your work, {name}.", objectives = "Obtain 11 Mao-Willows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30965] = { id = 30965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herding Cats", description = "Xuen trusted me to watch kittens. I like kittens. They are small things and funny.\n\nBut I lost kittens. They are strong and many.\n\nXuen sure to say I can no longer watch kittens. I must find kittens. Will you help?\n\nTake my special cage and it will put them in a safe place.", objectives = "Collect 8 Litters of Xuen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30967] = { id = 30967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Dissenters", description = "Not all of my fellow villagers from Inkgill are corrupted. Many heeded my warnings and did not drink of the sha-tainted waters.\n\nThey are in hiding, terrified, and intimidated by the guards.\n\nPlease, tell them there is hope! Go into the village to the north. Speak with them and send them to me.", completion = "Though we may not seem like much, from these inauspicious beginnings I know we will rebuild. Thank you, friend.", objectives = "Rescue 6 Inkgill Dissenters in Inkgill Mere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30968] = { id = 30968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sha of Hatred", description = "The end of our hunt is upon us. We have gathered the strongest the Shado-Pan have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and choke out its influence on the world.\n\nWhen we enter the tunnel, stay close, and keep hatred clear from your heart. The fight ahead will put all of us to the test.\n\nWhatever happens, it has been an honor traveling beside you, {name}.", completion = "Defeating a Sha... is not an easy thing. It is a miracle that we came out of this unscathed.\n\nTaran still blames himself for letting his hatred get the best of him and setting this beast loose upon the land. It may take some time for him to come to terms with this, but it is important that he does, lest he be vulnerable again.\n\nWe accomplished a great thing this day, a thing that will not soon be forgotten.\n\nAnd neither shall you for your hand in this.  Thank you.", objectives = "Defeat the Sha of Hatred.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30969] = { id = 30969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Enemy", description = "The power of these Dark Shaman has attracted many allies, {name}. Former members of the Horde that now work towards some dark purpose.\n\nWe need to make an example of them before we have another twilight's hammer on our hands.\n\nKill any cultist you come across and bring me their insignia.", progress = "Have you collected the insignia?", completion = "Good work, {name}. This will make it very clear how Garrosh is going to deal with failures...", objectives = "Collect 5 Corrupted Insignia from any cultist in Ragefire Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30970] = { id = 30970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged By Hatred", description = "These scorpions are infected with sha. It seems to have driven them out of their hole and into our camp, seething with hatred at invaders in their territory.\n\nWe need to clear the scorpions and secure the camp. Kill any you find.", progress = "The Sha of Hatred's passing did this to them. I doubt this is the only thing that will have been affected by its passing.", completion = "Good. What's left of the camp will be a bit safer.", objectives = "Kill 9 Seething Fleshrippers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30971] = { id = 30971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Stock", description = "I was dispatched back to camp to gather pitch-tipped arrows for our archers at the bridge, and this is what I came to. I trained with most of these pandaren... I wasn't prepared for this.\n\nStill, the archers at the bridge need our help. If you could help gather arrows from the wreckage, then maybe we can salvage something from this horror.", progress = "The pandaren at the bridge are depending on us...", completion = "I... you... er, thank you. You didn't have to help, but you did. Thank you.", objectives = "Gather 120 Shado-Pan Fire Arrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30972] = { id = 30972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Fight", description = "Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?", progress = "Welcome to the mess.", completion = "Taran Zhu told me what became of my camp. I would have stopped it if I could, but the attacks from the bridge have not let up.\n\nThank you for bringing these arrows - my archers will make good use of them.", objectives = "Bring the Quiver of Shado-Pan Fire Arrows to Lao-Chin the Iron Belly at Dusklight Bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30973] = { id = 30973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up In Flames", description = "The mantid coming across the bridge have thick carapaces that shrug off most of our attacks. They have a weakness though: fire.\n\nLao-Chen's men brought kegs to the battlefield for exactly this purpose.  Kick the kegs into groups of mantid, and Lao-Chin's archers will light them up.\n\nThey should be easy to finish off from there.", progress = "Creative solution.  Lao-Chin impresses.", completion = "We have the added benefit that the mantid will leave with broken morale after watching their brethren burn to death.  Grim, but many lives will be spared if they simply stop pressing our lines.", objectives = "Kill 10 Kor'thik Timberhusks with the aid of Lao-Chin's kegs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30974] = { id = 30974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Spirits", description = "The kegs are full of my worst stock. Good for burning, crap for drinking.\n\nI've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men!  Spirits to raise their spirits after endless, grueling fighting.\n\nWould you be up for spreading the good cheer?", objectives = "Throw 8 Iron Belly Spirits to nearby Dusklight Skirmishers and Dusklight Rangers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30975] = { id = 30975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taking of Dusklight Bridge", description = "Let's press these insects back across the bridge and break their spirits!\n\nFollow my lead.", completion = "The mantid aren't likely to return soon after a beating like that... and now Lao-Chin is free to join us in the hunt.", objectives = "Help Lao-Chin the Iron Belly hold the far side of the Dusklight Bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30976] = { id = 30976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Hunt", description = "We are one stronger. Your help is invaluable.\n\nLet's move on westward to Rensai's Watchpost to find the last member for our party.", completion = "We are close. I can feel the unnatural hatred surging.\n\nIt's a testament to the training of the Shado-Pan that the forces here have not been consumed by its influence.", objectives = "Ride with Taran Zhu, Taoshi, and Lao-Chin to Rensai's Watchpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30977] = { id = 30977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grounded Welcome", description = "All of my men are down at Farwatch Overlook to the southwest, holding off mantid that are trying to fly across the chasm. As long as my marksmen have arrows, they'll ground any mantid that clear the chasm.\n\nIf you're here to help, I could use some more men clearing the mantid out once they're on the ground. Are you willing, {class}?", completion = "Your efforts are appreciated, {class}. Even a few more moment's breath between attacks are a relief these days.", objectives = "Kill 12 grounded Kor'thik Fleetwings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30978] = { id = 30978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Skies", description = "We're about to get hit hard... \n\nPick up that cannon there and lend a hand, if you would.  There will be no shortage of targets.", progress = "I could really use you on that cannon...", completion = "Excellent shooting!\n\nI'm pretty sure that big bug survived the fall though...", objectives = "Shoot down 50 Kor'thik Swarmers and Voress'thalik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30979] = { id = 30979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devastation Below", description = "Let's get down there and finish that big bug off, you and I.", completion = "Where have you been all my life?!  That was amazing!\n\nI'd be proud to fight beside you any day.", objectives = "Defeat Voress'thalik with the aid of Hawkmaster Nurong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30980] = { id = 30980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of the Shado-Pan", description = "You said that Taran Zhu is in Townlong and was asking for me?  Must be something important...", completion = "I like that I can always depend on you. You have the spirit of a true Shado-Pan.", objectives = "Return with Hawkmaster Nurong to Taran Zhu at Rensai's Watchpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30981] = { id = 30981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taoshi and Korvexxis", description = "Taoshi is setting up an ambush for one of the mantid leaders on the south side of Sik'vess. She is tasked with retrieving his crystal so that we can use it to open the door.\n\nTwo are stronger than one. I want you there to make sure it goes smoothly.", progress = "Our hunt is nearly over...", completion = "The first crystal is ours...", objectives = "Kill Korvexxis with the aid of Taoshi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30982] = { id = 30982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animal Control", description = "The chasm is overrun with flame hounds and lava worms, and they will be entrenched indefinitely with such a large supply of trogg flesh for food.\n\nThis infestation needs to be taken care of now, before they endanger the city. You look like you can handle yourself, {name}.\n\nI want you to clear a path through the beasts and make certain to take out the largest threats, Adjules and Magnaw.", completion = "Good work, {name}. Who knows what kind of destruction those beasts would have caused.", objectives = "Kill Adarogg and Slagmaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30983] = { id = 30983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Horde. That's where you come in, {name}.\n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", progress = "Yes?", completion = "It would seem that the dark shaman experiments drove Gordoth insane.\n\nHopefully we've seen the last of this, {name}.", objectives = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30984] = { id = 30984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Orc Left Behind", description = "This was supposed to be a routine sweep, {name}. Clean up a few troggs, make sure there is no threat to the city and then be in the tavern by midday.\n\nInstead I've a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on about \"the next twilight's hammer.\"\n\n<Commander Bagran spits>\n\nGo in there and get my scouts back so we can figure out what is going on down here.", progress = "Have you found the scouts?", completion = "That's all that survived?\n\nI don't know who these Dark Shaman are working for, but they are going to pay for this.", objectives = "Rescue 5 Kor'kron Scouts in Ragefire Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30986] = { id = 30986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mogu Crypt", description = "Our scouting party got DESTROYED.  Help!", objectives = "Kill the possessed Shado-Pan Leader and cleanse the Pool of Life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30987] = { id = 30987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Alliance", description = "We have a duty, {name}.\n\nIt is our responsibility to spread the Tushui philosophy beyond the edges of the Wandering Isle... and there is no better place to start doing that than here: Stormwind City, heart of the Alliance.\n\nLet's find out who their leader is. We need allies.", completion = "{race}... you're here.\n\nGood.", objectives = "Speak with King Anduin Wrynn at Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30988] = { id = 30988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Way", description = "I only recently received word that some of your kind might be coming our way. I'd be glad to call you an ally, if you're willing to join our cause.\n\nWalk with me, {name}.", completion = "Before you go, {name} - I have one more thing to discuss with you.", objectives = "Walk with King Varian Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30989] = { id = 30989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Pit Fighter", description = "I need to know if you can fight. There may come a time where you will be called upon for military matters, and I need to know that you can protect my kingdom.\n\nI've heard stories about pandaren fighting techniques, but I've never seen them in person.\n\nShall we?", completion = "You've more than proven your worth, in battle and in heart. Few would be willing to leave their homeland to join the Alliance. Fewer still would be willing to face the King of Stormwind in combat.\n\nYou, and the rest of your people, are welcome among our ranks. Welcome to the Alliance, {name}.", objectives = "Spar with King Varian Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30990] = { id = 30990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open the Golden Doors", description = "Defeat the mogu crypt guardian to open the golden doors.", objectives = "Defeat the Mogu Crypt Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30991] = { id = 30991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do a Barrel Roll!", description = "When I trained as a Brewmaster, I didn't expect to use my knowledge like this...\n\nDid you know beer catches fire when lit? Well, with yaungol oil mixed in, it's downright explosive.\n\nI've mixed the oil in with these kegs. Roll them at the yaungol over by the gate, and ignite them when you get close. \n\nIt'll take a few seconds for the keg to blow, but when it does...\n\nWell, let's just say I wouldn't want to be over there.\n\nWhich is why I'll be over here. Mourning the loss of this brew.", progress = "Wha? I was just thinking about my poor, poor beer...", completion = "Whoo, that was an explosion! Several, in fact.\n\nSad my beer had to go, but at least we're safe, for now.", objectives = "Pick up a keg near Lao-Chin, roll it downhill at the yaungol, and ignite it near them to destroy 4 Osul Treelaunchers and 50 Osul Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30992] = { id = 30992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish This!", description = "We've heard back from Suna, on the wall. Something's going on...\n\nIt looks like they are preparing for their final push. It's time to finish this, friend.", progress = "Lin is captured... we must break Taran Zhu from his complacence!", completion = "Well, their lieutenant is dead. I think we have finally pushed them out of Kun-Lai. \n\nBut at what cost? So many dead, Lin captured... I will not allow Taran Zhu to continue to ignore his charge.", objectives = "Finish the battle for the Ox Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30993] = { id = 30993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where are My Reinforcements?", description = "This has simply gone too far. I cannot ignore our abandonment any longer.\n\nAfter all that's happened here, and all you've been through in Firebough, we must travel to the monastery.\n\nWhatever they are doing in there can wait! We can take my balloon up the mountain to the Monastery. It's anchored back by the camp, to the northeast.", progress = "Here we are, then.", completion = "Here we are, and now you know why we cannot let our brothers sit idly by.", objectives = "Speak with Ban Bearheart outside the Shado-Pan Monastery in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30994] = { id = 30994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Chin's Gambit", description = "Alright. Thanks to you, we have the wall under control. Good job. \n\nI'll stay up here for a little while and make sure no more yaungol get up onto the wall.\n\nYou, though, should go back down and see what Lao-Chin has cooked up. I hate to say it, but maybe he had a good idea after all...", progress = "Ah, hello again. As sad as I am to have to do this, I'm glad I came up with something.", completion = "Good to see you made it back in one piece. Thanks to your help with the barrels, I've managed to brew up a good surprise for our yaungol friends at the front.", objectives = "Speak with Lao-Chin the Iron Belly at Winter's Blossom in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30995] = { id = 30995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Man Left Behind", description = "I sent recon out over an hour ago and none of them have reported back. And now these damned hounds are pouring out of the chasm.\n\nI don't know what's going on down there, but I'm not going anywhere till I get my men back.\n\nI want you to head in there and find them, {name}, preferably while they are still alive.", progress = "Have you found all the rangers?", completion = "That's all that survived?\n\nThe Horde is going to pay for this in blood.", objectives = "Rescue 5 SI:7 Rangers in Ragefire Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30996] = { id = 30996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Alliance. And I need your help stopping them, {name}. \n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", completion = "It would seem that the dark shaman experiments drove Gordoth insane.\n\nHopefully we've seen the last of this, {name}.", objectives = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30997] = { id = 30997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animal Control", description = "I'm glad you're here, {name}. The horde is amassing an army and I'm not going to wait to find out why.\n\nWe need to strike fast and take down some of the larger beasts they have down here.\n\nI want you to head in there and take care of Adarogg and Slagmaw before the horde can use them as weapons against us.", completion = "Good work, {name}. Who knows what kind of destruction those beasts would have caused.", objectives = "Kill Adarogg and Slagmaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30998] = { id = 30998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Enemy", description = "The horde is using dark magic to control beasts and corrupt their brethren down here, {name}.\n\nI intend to put a stop to it, but first I need to know what it is we're fighting against. That's where you come in.\n\nFight through the caverns and collect the insignia that the cultists carry. With them, I can study what type of magic is at work here.", progress = "Have you collected the insignia?", completion = "Good work, {name}. Now we can figure out what it is they were trying to achieve down here.", objectives = "Collect 5 Corrupted Insignia from the Dark Shaman cultists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30999] = { id = 30999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path Less Traveled", description = "The toughest roads often have the most to teach us, {class}. I will no doubt learn a great deal from following the path of Shaohao.\n\nMany years ago Shaohao traveled to the highest peak in Kun-Lai to seek the guidance of the Jade Serpent. I too will travel to Seeker's Point in search of wisdom.\n\nPerhaps you would be interested in a journey such as this? If so speak with Uncle Cloverleaf. He will help you prepare.", completion = "Travel to Seeker's Point will require much good fortune, {class}. Hopefully you have many lucky trinkets!", objectives = "Speak to Uncle Cloverleaf in Onekeg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31000] = { id = 31000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", objectives = "Speak with Bowmistress Li on the Serpent's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31001] = { id = 31001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling Down", description = "It's bad enough trying to hold off the mantid, but now we've got spiders swarming up from the ruins below.\n\nOne of my best marksmen caught a blast of webbing around his leg and got pulled straight down!\n\nWe think he's alive, but I don't have the manpower to send anyone in after him. We're stretched thin up here, {class}.\n\nIf you want to help, use the rope behind me to drop down into the ruins. You're not afraid of heights are you?\n\nHow about spiders?", completion = "The fall wasn't that bad, actually. I've always had a knack for soft landings.\n\nThat I landed on a pile of spider corpses probably helped, too.", objectives = "Use the Shado-Pan Rope to descend into the Terrace of Gurthan and search for the fallen Shado-Pan marksman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31002] = { id = 31002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nope", description = "We're holding, but just barely. Anything you can do to stem the tide of dreadspinners coming up the wall would be a big help.\n\nFeel like tearing open spider eggs one at a time by hand?\n\nI didn't think so. Take one of our dragon guns and light it up down there. I wanna hear those puppies pop.", progress = "Hey, help me out here!", completion = "Nice work with that dragon gun. I did what I could down here, but arrows are only so useful against these things.", objectives = "Slay 6 Dreadspinner Tenders and use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in the Terrace of Gurthan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31003] = { id = 31003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Psycho Mantid", description = "You aren't going to believe what I saw! Two mantid fighting each other, whipping some serious magic back and forth.\n\nOne of them didn't look like any mantid I've ever seen. Completely different color and dress to him, like some kind of... oracle or something. The other one was a total psycho, splashing sha energy around like it was a keg of Stormstout Special.\n\nLook, I gotta get back to my post, but those two are still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?", progress = "The empress... is... misguided.", completion = "<This mantid is severely wounded. He barely manages to choke forth his words between wheezing gasps for breath.>\n\nHold, {race}...\n\nWe are... not your enemy.", objectives = "Investigate the mantid infighting at the Terrace of Gurthan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31004] = { id = 31004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserved in Amber", description = "Take... this...\n\n<The dying mantid struggles to outstretch his arm. In his mangled grasp rests a metal fork with two long, thin prongs and an ornately jeweled handle.>\n\nAwaken... the Wind-Reaver...\n\nIt is the only way... to end the swarm.", completion = "The Klaxxi... call to me.", objectives = "Use the Klaxxi Tuning Fork on the Ancient Amber Chunk in the Terrace of Gurthan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31005] = { id = 31005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wakening Sickness", description = "You will forgive my current state. I have slept for many years.\n\nA Klaxxi'va should have been here to attend my Wakening with kypari sap... but you will have to do.\n\nI sense the buzzing of sapflies to the south. They gorge on the nourishing sap I need. Bring them to me.", progress = "Without nourishment, I will die where I stand.", completion = "This will do.", objectives = "Bring 100 Sapfly Bits to Kil'ruk the Wind-Reaver in the Terrace of Gurthan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31006] = { id = 31006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Klaxxi Council", description = "I must report to the Klaxxi. They would not have woken me unless the situation were dire.\n\nYou have not been entirely useless. For that, I will spare your life.\n\nThe council may even find a use for you.", completion = "This is a sacred meeting place for the Klaxxi.\n\nIt would be wise of you to let me do the talking.", objectives = "Travel to Klaxxi'vess at the center of the Dread Wastes. You may speak with Kil'ruk the Wind-Reaver in the Terrace of Gurthan for a ride, or travel on your own.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31007] = { id = 31007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Clutches", description = "The imperial clutches have become an abomination! Clutch-Keepers rush the development of new swarmborn, saturating them in this vile \"sha\" energy before sending them away to the wall.\n\nThe Klaxxi wish to stem the tide of swarmborn production in these dread clutches. Put the keepers to death!", completion = "A few less traitors for us to feed to the kunchong when the dust settles.", objectives = "Slay 6 Shek'zeer Clutch-Keepers in the Clutches of Shek'zeer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31008] = { id = 31008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amber Arms", description = "You! Filth!\n\nYou work for me now!\n\nThe amber blades of the Shek'zeer Bladesworn are the finest weapons in the empire.\n\nIf you are not impaled upon them immediately after leaving here, bring me as many of the blades as you can carry! I want to make sure we have weapons in reserve, should we need them.", progress = "The bladesworn carry their swords with pride. I want them on my weapon racks!", completion = "If all goes as planned, the Klaxxi will stop the Empress without your help. Still, it is my role to be prepared.", objectives = "Gather 6 Amber Blades from Shek'zeer Bladesworn around the Heart of Fear and The Clutches of Shek'zeer.\n\nSpeak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31009] = { id = 31009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Zone", description = "A Klaxxi'va whispers to the tower. It carries their whisper far; to other towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear it.\n\nThis way, they see all.\n\nA tower near the palace is quiet. This will not do. It must sing for the Klaxxi.\n\nIt is my job to fix the tower, but if you serve the Klaxxi, you should serve me as well. You fix the tower, and I will wait here!", objectives = "Use the Klaxxi Resonating Crystal on the Inactive Sonic Relay at the Heart of Fear.\n\nSpeak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31010] = { id = 31010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Her Clutch", description = "The crystal sings to the Klaxxi. They sense a paragon in the clutch, east of the tower.\n\nClutch-keepers are trying to pollute this one. the Klaxxi will not permit this.\n\nGo and find the paragon. Place your hands on his chamber, and the Klaxxi will channel their whispers through you to break him free. Protect him if you can.", completion = "My slumber was interrupted by sudden dreams. Unspeakable nightmares.\n\nThen I awoke.\n\nThe Klaxxi have spoken to me. I have my orders. There is much to be done.", objectives = "Locate and waken the mantid paragon in The Clutches of Shek'zeer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31011] = { id = 31011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies At Our Door", description = "The Zandalari have begun their attack! You must help defend the village!\n\nIf we can't push them back, we will never find the Thunder King's remains!", progress = "The village must be saved!", completion = "The Zandalari have started to retreat, {name}. This victory will mean a great deal to the villagers.\n\nIn the chaos I was able to capture one of the fighters. Perhaps we can get information from him.", objectives = "Defeat 10 Amani Beserkers, 5 Amani Behemoths, and 3 Gurubashi Bloodriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31012] = { id = 31012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Horde", description = "Here we are, {name}... Orgrimmar, heart of the Horde.\n\nWe can be helpful beyond the edges of the Wandering Isle. There are innumerable problems out there, just waiting for us to solve them. This is what Master Shang Xi would have wanted.\n\nThere's no better place to start doing that than here, with the aid of the Horde. Let's find out who their leader is. We need allies.", completion = "{race}... you're here.\n\nGood.", objectives = "Speak with Garrosh Hellscream in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31013] = { id = 31013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Way", description = "I recently received word that some of your kind might be coming our way.\n\nI've recently been trying to bolster the strength of the Horde. A few pandaren might do us good.\n\nWalk with me, {name}.", completion = "Ji. {name}. You're here, good.\n\nLet's keep this moving.", objectives = "Walk with Garrosh Hellscream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31014] = { id = 31014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Gift", description = "I need to know if you can fight... that you can kill, and live. Eventually, each of you will be called upon for war, and I need to know that you can be counted on.\n\nI mentioned a gift earlier. It lies here, within the Ring of Valor. Step into the arena, right through this door behind me. I will test your skills.", completion = "You've more than proven your worth, in battle and in heart. Few would be willing to leave their homeland to join the Horde. Fewer still would be willing to face a charging magnataur in combat.\n\nYou, and the rest of your people, are welcome among our ranks. Welcome to the Horde, {name}.", objectives = "Complete Garrosh's test by defeating Oggax, Gadoon, and Frozengore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31015] = { id = 31015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Private Collection", description = "Pandaria is rich with history, legends, stories, and lore of every sort. While you are traveling throughout the world I would ask that you keep an eye open for artifacts and pieces of information that you feel would be pertinent to our work here.\n\nWhen you accumulate enough knowledge, we will compile it in to a volume for your personal collection here.\n\nYou can, of course, return whenever you like to review the volumes we are making for you.", progress = "So much to learn.", completion = "Ah! Now that that is done we can start to place your collected research here. I look forward to seeing what you find.", objectives = "Clean off the Empty Bookshelf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31016] = { id = 31016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lorewalkers", objectives = "Speak with Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31017] = { id = 31017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Humble Grummle", objectives = "Bring The Humble Grummle to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31018] = { id = 31018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Heart of Fear", description = "The Klaxxi have detected the existence of another paragon, Wakener.\n\nThis one was kept well-hidden from us, and for good reason.\n\nThe Empress already has possession of this one, and her adjuncts work to destroy it even now.\n\nThey are performing their sorcery in a chamber deep beneath the palace, and they must be stopped.\n\nWe hold Klaxxi'vess. You must go in our stead. Find the entrance to their chamber from the ledge to the west.", completion = "You have done your duty well, Wakener.", objectives = "Kill Adjunct Ek'vem, Adjunct Ikkess, Adjunct Suruz, and Adjunct Tsikzi, and then free Xaril the Poisoned Mind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31019] = { id = 31019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amber Is Life", description = "In order for our efforts against the mantid empire to continue, we require more amber.\n\nThere is a great deposit of amber underneath the lake to the south, but the area is inhabited by a savage saurok tribe.\n\nI cannot spare anyone else. You must go to the lake and test the tribe's strength. Thin their numbers and eliminate their leader, who is probably hiding in his underground cavern.\n\nSurely this is not too great a task for you?", progress = "The amber looks familiar for some reason...", completion = "The whispers seem to be emanating from within this amber.\n\nCould there be another paragon sleeping within?", objectives = "Kill 7 Mistblade Rippers and the Mistblade Scale-Lord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31020] = { id = 31020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Beast", description = "I must join the Klaxxi Council and the other paragons immediately, but I am barely strong enough to stand.\n\nI must feed, Wakener.\n\nI sense the beating hearts of creatures on the northern bank of the lake.\n\nKill them for me, and I shall do the rest.", progress = "I have been sleeping for many thousands of years. I must regain my strength before rejoining the Council.", completion = "I feel the strength returning to my body.", objectives = "Kill 8 Coldbite Crocolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31021] = { id = 31021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Amber", description = "Liquid amber is most efficient for restoring a newly awakened paragon's strength, and is usually provided at a wakening ceremony.\n\nUnfortunately, it seems you did not receive these instructions, so we shall have to improvise.\n\nI can sense a vast quantity of fossilized amber in the lake below us. It will serve, but I am too weak to dig it up myself.\n\nDo this for me, and I will see to it that you are rewarded.", progress = "Do you understand, Wakener? The amber gives life.", completion = "Thank you, Wakener. That is enough for now.", objectives = "Collect 8 Living Amber, then feed them to Korven the Prime.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31022] = { id = 31022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kypari Zar", description = "What is that tree on the hill to the west? Can it be... Kypari Zar?\n\n<Korven the Prime lapses into silence.>\n\nWhen I returned from my final ravage, before being elevated to a paragon, I was given the honor of planting that very tree.\n\nI see it has grown into a great kypari, but... it seems something is amiss.\n\nThere is an old sonar tower at the base of the tree. Take me there, Wakener. I can use the tower to take a closer look.", progress = "What has happened to our home? Things feel amiss.", completion = "Once, great rivers of amber coursed through this tree's veins. Now, it is but a dried husk.", objectives = "Activate the Sonar Tower, then defend Korven the Prime as he examines the tree.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31023] = { id = 31023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Swarm", description = "This strange-looking carving is covered in a complex written language that might be mantid in origin.\n\nYou notice more relics strewn carelessly among the camps and inside the lake.\n\nPerhaps the Klaxxi would be interested in examining these artifacts.\n\nWho knows? Perhaps it will earn you some favor.", progress = "What do you have there?", completion = "These relics describe the history of Kypari Vos and the nearby amber trees.\n\nI would like to study these.\n\nThank you, {class}.", objectives = "Collect 8 Mantid Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31024] = { id = 31024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunchong Treats", description = "As Kovok grows, he will require equal parts discipline and reward.\n\nI lack no shortage of discipline, but our supply of meat is almost empty.\n\nTo the south, you will find turtles roaming north of the Lake of Stars and Kypari Zar.\n\nHunt them. Kovok likes the taste of their flesh.", progress = "What have you brought for Kovok?", completion = "Yes, a worthy feast.\n\nWell done.", objectives = "Collect 4 Meaty Turtle Haunches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31025] = { id = 31025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Tooth", description = "We cannot summon a god without a worthy offering.\n\nI have noticed a rare flower growing among the fields to the north.\n\nThe Starshade is a potent flower whose bloom holds a powerfully sweet, intoxicating liquor.\n\nA single taste of this heady substance invigorates and strengthens the body.\n\nSurely, this god will appreciate its worth.", objectives = "Collect 50 Starshade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31026] = { id = 31026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of the Problem", description = "Kypari Zar is dying.\n\nA creature of terrible darkness corrupts it from deep beneath its roots.\n\nThe tree cannot be saved, but at least we can lessen its pain.\n\nLook. The vile creature has carved a path to its own lair. We need only follow it down the hill, just behind this tower.", progress = "The swarm knows not of their terrible folly! These precious trees must be protected at all costs!", completion = "Thank you, Wakener. Kypari Zar can now dream in peace.\n\nHowever, the beast was merely a vessel for the corruption.\n\nNo... the true corruption lies much deeper.", objectives = "Kill the Coldbite Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31027] = { id = 31027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat the Abomination", description = "Now that the pool of life is cleansed, the way to the crypt's interior is open.  Make your way down there and defeat the abomination.", objectives = "Defeat the Abomination of Anger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31028] = { id = 31028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon 5", description = "The emanations are growing stronger, {class}.\n\nI feel them coming from the cave below us.\n\nI wish to study the beast that you have slain, so I will grant you the honor of awakening the next paragon.\n\nAfter all, the danger should be past.\n\nGo now, wallstrider, before I change my mind.", objectives = "Recover the fifth paragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31030] = { id = 31030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", completion = "You have come. Good. This is a calamitous situation.", objectives = "Meet Ban Bearheart inside the Shado-Pan Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31031] = { id = 31031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", completion = "You have come. Good. This is a calamitous situation.", objectives = "Meet Ban Bearheart inside the Shado-Pan Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31032] = { id = 31032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choking the Skies", description = "Nurong wants me to pass out torches for burning the bodies.\n\nThe flying mantid are fragile, and won't last long in the hot smoke.", progress = "Some of them can make it through the smoke, but in small enough numbers that we can easily pick them off.", completion = "Your help is appreciated, stranger.", objectives = "Burn 10 Kor'thik Fleetwing corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31033] = { id = 31033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Dark Shaman are poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Commander Bagran, head of the defense initiative, to end the threat to Orgrimmar once and for all.", sourceObjective = "Speak with Commander Bagran.", sourceObjectiveStatus = "unverified-source-field" }
quests[31034] = { id = 31034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Commander Bagran just inside Ragefire Chasm. He will have further orders for you.", completion = "I've been expecting your arrival, {name}.", objectives = "Speak with Commander Bagran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[31035] = { id = 31035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.", sourceObjective = "Speak with Stone Guard Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
